def build_tradingview_symbol(ticker):
    ticker_upper = ticker.strip().upper()
    if ticker_upper.endswith(".NS"):
        return f"NSE:{ticker_upper.replace('.NS', '')}"
    if ticker_upper.endswith(".BO"):
        return f"BSE:{ticker_upper.replace('.BO', '')}"
    if ":" in ticker_upper:
        return ticker_upper
    if ticker_upper.endswith("=X"):
        return ticker_upper.replace("=X", "")
    return f"NASDAQ:{ticker_upper}"


def normalize_ticker_for_asset(ticker, asset_type):
    raw = ticker.strip().upper()
    if asset_type == "forex":
        cleaned = raw.replace("/", "")
        if cleaned.endswith("=X"):
            return cleaned
        if len(cleaned) == 6 and cleaned.isalpha():
            return f"{cleaned}=X"
        return cleaned
    if asset_type == "bond":
        cleaned = raw.replace(" ", "")
        if cleaned in TREASURY_NODE_MAP:
            return cleaned
        return cleaned
    return raw


def period_to_date_range(period):
    period = (period or "1y").strip().lower()
    now = pd.Timestamp.utcnow().tz_localize(None)
    if period.endswith("y") and period[:-1].isdigit():
        years = int(period[:-1])
        return now - pd.DateOffset(years=years), now
    if period.endswith("mo") and period[:-2].isdigit():
        months = int(period[:-2])
        return now - pd.DateOffset(months=months), now
    if period.endswith("m") and period[:-1].isdigit():
        months = int(period[:-1])
        return now - pd.DateOffset(months=months), now
    if period.endswith("d") and period[:-1].isdigit():
        days = int(period[:-1])
        return now - pd.Timedelta(days=days), now
    return now - pd.DateOffset(years=1), now


def resolve_series_window(stock_data):
    frame = normalize_price_dataframe(stock_data)
    if frame is None or frame.empty:
        return None, None
    try:
        idx = pd.to_datetime(frame.index)
        return pd.to_datetime(idx.min()), pd.to_datetime(idx.max())
    except Exception:
        return None, None


def fetch_treasury_node_data(symbol, period="1y", start_date="", end_date=""):
    node = TREASURY_NODE_MAP.get(symbol)
    if not node:
        return pd.DataFrame()

    if start_date and end_date:
        start = pd.to_datetime(start_date)
        end = pd.to_datetime(end_date)
    else:
        start, end = period_to_date_range(period)

    series = fetch_fred_series(node["series"], start, end)
    if series.empty:
        return pd.DataFrame()

    yield_series = series.dropna().astype(float)
    if yield_series.empty:
        return pd.DataFrame()

    duration = float(node["duration"])
    base_yield = float(yield_series.iloc[0])
    synthetic_close = 100 * np.exp(-duration * ((yield_series - base_yield) / 100.0))
    open_series = synthetic_close.shift(1).fillna(synthetic_close)
    range_pad = synthetic_close.abs() * 0.0012
    high_series = pd.concat([open_series, synthetic_close], axis=1).max(axis=1) + range_pad
    low_series = pd.concat([open_series, synthetic_close], axis=1).min(axis=1) - range_pad

    frame = pd.DataFrame({
        "Open": open_series,
        "High": high_series,
        "Low": low_series,
        "Close": synthetic_close,
        "Adj Close": synthetic_close,
        "Volume": 0,
    })
    frame.index.name = "Date"
    return frame


def get_timeline_presets():
    presets = {"period": "Quick period"}
    for key, meta in CRISIS_PRESET_LIBRARY.items():
        presets[key] = meta["label"]
    presets["custom"] = "Custom date range"
    return presets


def fetch_stock_data(ticker, period, timeline_preset, start_date, end_date, asset_type="stock"):
    preset_ranges = {
        key: (meta["start"], meta["end"])
        for key, meta in CRISIS_PRESET_LIBRARY.items()
    }

    period = period or "1y"
    timeline_label = f"Period mode ({period})"

    def safe_download(symbol, start_val, end_val):
        try:
            return normalize_price_dataframe(
                yf.download(symbol, start=start_val, end=end_val, interval="1d", progress=False)
            )
        except Exception:
            return pd.DataFrame()

    def fallback_candidates():
        if asset_type == "bond":
            return ["TLT", "IEF", "^TNX", "^DJI", "^GSPC"]
        if asset_type == "forex":
            return ["UUP", "FXE", "^DJI", "^GSPC"]
        return ["^DJI", "^GSPC", "SPY", "QQQ"]

    def resolve_window_dates(preset_key):
        preset_start, preset_end = preset_ranges[preset_key]
        if preset_end == "present":
            today = pd.Timestamp.utcnow().date()
            if asset_type == "bond":
                resolved_end = today.isoformat()
            else:
                resolved_end = (pd.Timestamp(today) + pd.Timedelta(days=1)).strftime("%Y-%m-%d")
            label_end = today.isoformat()
        else:
            resolved_end = preset_end
            label_end = preset_end
        return preset_start, resolved_end, label_end

    if asset_type == "bond" and ticker in TREASURY_NODE_MAP:
        if timeline_preset in preset_ranges:
            start_date, end_date, label_end = resolve_window_dates(timeline_preset)
            stock_data = fetch_treasury_node_data(ticker, period=period, start_date=start_date, end_date=end_date)
            timeline_label = f"{get_timeline_presets()[timeline_preset]} | {start_date} to {label_end}"
        elif timeline_preset == "custom" and start_date and end_date:
            stock_data = fetch_treasury_node_data(ticker, period=period, start_date=start_date, end_date=end_date)
            timeline_label = f"Custom range ({start_date} to {end_date})"
        else:
            stock_data = fetch_treasury_node_data(ticker, period=period, start_date="", end_date="")

        if stock_data is None:
            stock_data = pd.DataFrame()

        if stock_data.empty and timeline_preset in preset_ranges:
            fallback_symbol = None
            fallback_data = pd.DataFrame()
            for candidate in fallback_candidates():
                fallback_data = safe_download(candidate, start_date, end_date)
                if not fallback_data.empty:
                    fallback_symbol = candidate
                    break
            if fallback_symbol:
                stock_data = fallback_data
                timeline_label = f"{timeline_label} | No historical data for {ticker}; fallback benchmark {fallback_symbol}"
            else:
                stock_data = fetch_treasury_node_data(ticker, period=period, start_date="", end_date="")
                if stock_data is None:
                    stock_data = pd.DataFrame()
                if not stock_data.empty:
                    timeline_label = f"{timeline_label} | Window data unavailable for {ticker}; fallback to period mode ({period})"

        stock_data = normalize_price_dataframe(stock_data)
        timeline_label = f"Bond timeline ({timeline_label})"
        return stock_data, timeline_label

    if timeline_preset in preset_ranges:
        start_date, end_date, label_end = resolve_window_dates(timeline_preset)
        stock_data = safe_download(ticker, start_date, end_date)
        timeline_label = f"{get_timeline_presets()[timeline_preset]} | {start_date} to {label_end}"
    elif timeline_preset == "custom" and start_date and end_date:
        stock_data = safe_download(ticker, start_date, end_date)
        timeline_label = f"Custom range ({start_date} to {end_date})"
    else:
        stock_data = yf.download(ticker, period=period, interval="1d")

    if stock_data is None:
        stock_data = pd.DataFrame()

    if stock_data.empty and timeline_preset == "custom":
        stock_data = yf.download(ticker, period=period, interval="1d")
        timeline_label = f"No data for custom range, fallback to period mode ({period})"

    if stock_data.empty and timeline_preset in preset_ranges:
        fallback_symbol = None
        fallback_data = pd.DataFrame()
        for candidate in fallback_candidates():
            fallback_data = safe_download(candidate, start_date, end_date)
            if not fallback_data.empty:
                fallback_symbol = candidate
                break
        if fallback_symbol:
            stock_data = fallback_data
            timeline_label = f"{timeline_label} | No historical data for {ticker}; fallback benchmark {fallback_symbol}"
        else:
            stock_data = normalize_price_dataframe(yf.download(ticker, period=period, interval="1d", progress=False))
            if stock_data is None:
                stock_data = pd.DataFrame()
            if stock_data.empty:
                for candidate in fallback_candidates():
                    stock_data = normalize_price_dataframe(yf.download(candidate, period=period, interval="1d", progress=False))
                    if stock_data is not None and not stock_data.empty:
                        timeline_label = f"{timeline_label} | Crisis window unavailable; fallback to period proxy {candidate} ({period})"
                        break
            else:
                timeline_label = f"{timeline_label} | Crisis window unavailable; fallback to {ticker} period mode ({period})"

    if stock_data is None:
        stock_data = pd.DataFrame()

    stock_data = normalize_price_dataframe(stock_data)

    if asset_type == "forex":
        timeline_label = f"Forex timeline ({timeline_label})"
    elif asset_type == "bond":
        timeline_label = f"Bond timeline ({timeline_label})"

    return stock_data, timeline_label


def normalize_price_dataframe(stock_data):
    if stock_data is None:
        return pd.DataFrame()
    if isinstance(stock_data.columns, pd.MultiIndex):
        stock_data.columns = stock_data.columns.get_level_values(0)
    return stock_data


def build_timeline_summary(stock_data):
    if stock_data is None or stock_data.empty:
        return {
            "start": "N/A",
            "end": "N/A",
            "change_pct": "N/A",
            "high": "N/A",
            "low": "N/A",
            "avg_volume": "N/A",
            "volatility": "N/A",
            "sessions": 0,
        }

    close_col = "Adj Close" if "Adj Close" in stock_data.columns else "Close"
    close_series = stock_data[close_col].dropna()
    volume_series = stock_data["Volume"].dropna() if "Volume" in stock_data.columns else pd.Series(dtype=float)

    if close_series.empty:
        return {
            "start": "N/A",
            "end": "N/A",
            "change_pct": "N/A",
            "high": "N/A",
            "low": "N/A",
            "avg_volume": "N/A",
            "volatility": "N/A",
            "sessions": int(len(stock_data.index)),
        }

    start_price = float(close_series.iloc[0])
    end_price = float(close_series.iloc[-1])
    change_pct = ((end_price - start_price) / start_price) * 100 if start_price else 0
    high_price = float(close_series.max())
    low_price = float(close_series.min())
    avg_volume = float(volume_series.mean()) if not volume_series.empty else 0
    returns = close_series.pct_change().dropna()
    volatility = float(returns.std() * (252 ** 0.5) * 100) if not returns.empty else 0

    return {
        "start": f"${start_price:,.2f}",
        "end": f"${end_price:,.2f}",
        "change_pct": f"{change_pct:,.2f}%",
        "high": f"${high_price:,.2f}",
        "low": f"${low_price:,.2f}",
        "avg_volume": f"{avg_volume:,.0f}",
        "volatility": f"{volatility:,.2f}%",
        "sessions": int(len(close_series.index)),
    }


def _to_serializable_float(value, digits=2):
    if value is None or pd.isna(value):
        return None
    return round(float(value), digits)


def _closest_value(series, target_date):
    if series is None or series.empty:
        return None
    clean = series.dropna()
    if clean.empty:
        return None
    idx = clean.index.searchsorted(target_date, side="right") - 1
    if idx < 0:
        return None
    return clean.iloc[idx]


def compute_macro_regime_for_window(start_date, end_date):
    cpi = fetch_fred_series("CPIAUCSL", None, None)
    inflation_yoy = None
    if not cpi.empty:
        cpi_clean = cpi.dropna()
        end_val = _closest_value(cpi_clean, end_date)
        past_val = _closest_value(cpi_clean, end_date - pd.DateOffset(months=12))
        if end_val is not None and past_val is not None and float(past_val) != 0:
            inflation_yoy = ((float(end_val) / float(past_val)) - 1) * 100

    unemp_series = fetch_fred_series("UNRATE", start_date - pd.DateOffset(months=12), end_date)
    unemp = _closest_value(unemp_series, end_date)
    unemp_6m = None
    if unemp_series is not None and not unemp_series.empty:
        clean = unemp_series.dropna().tail(6)
        if not clean.empty:
            unemp_6m = clean.mean()

    y10_series = fetch_fred_series("DGS10", start_date - pd.Timedelta(days=40), end_date)
    y2_series = fetch_fred_series("DGS2", start_date - pd.Timedelta(days=40), end_date)
    y10 = _closest_value(y10_series, end_date)
    y2 = _closest_value(y2_series, end_date)
    curve_spread = None
    if y10 is not None and y2 is not None:
        curve_spread = float(y10) - float(y2)

    gdp = fetch_fred_series("GDPC1", None, None)
    growth_proxy = None
    if not gdp.empty:
        gdp_clean = gdp.dropna()
        end_gdp = _closest_value(gdp_clean, end_date)
        prev_gdp = _closest_value(gdp_clean, end_date - pd.DateOffset(years=1))
        if end_gdp is not None and prev_gdp is not None and float(prev_gdp) != 0:
            growth_proxy = ((float(end_gdp) / float(prev_gdp)) - 1) * 100

    pce_series = fetch_fred_series("PCEPI", None, None)
    pce_yoy = None
    if not pce_series.empty:
        pce_clean = pce_series.dropna()
        end_pce = _closest_value(pce_clean, end_date)
        prev_pce = _closest_value(pce_clean, end_date - pd.DateOffset(months=12))
        if end_pce is not None and prev_pce is not None and float(prev_pce) != 0:
            pce_yoy = ((float(end_pce) / float(prev_pce)) - 1) * 100

    score_expansion = 0
    score_recession = 0
    score_overheating = 0
    score_stagflation = 0

    inflation_ref = inflation_yoy if inflation_yoy is not None else pce_yoy
    if inflation_ref is None:
        inflation_ref = 2.5
    if growth_proxy is None:
        growth_proxy = 1.5
    if unemp is None:
        unemp = 4.5
    if unemp_6m is None:
        unemp_6m = unemp
    if curve_spread is None:
        curve_spread = 0.2

    if growth_proxy > 1.5 and inflation_ref < 3.5 and unemp <= 4.5:
        score_expansion += 3
    if growth_proxy < 0.8 or unemp > 5.2 or curve_spread < -0.2:
        score_recession += 3
    if growth_proxy > 2.0 and inflation_ref >= 3.5 and unemp < 4.2:
        score_overheating += 3
    if inflation_ref >= 3.5 and growth_proxy < 1.2 and unemp >= unemp_6m:
        score_stagflation += 4

    if curve_spread > 0.4:
        score_expansion += 1
    if curve_spread < 0:
        score_recession += 1
        score_stagflation += 1

    if inflation_ref > 4.2:
        score_overheating += 1
        score_stagflation += 1

    regime_scores = {
        "Expansion": score_expansion,
        "Recession": score_recession,
        "Overheating": score_overheating,
        "Stagflation": score_stagflation,
    }
    regime = max(regime_scores, key=regime_scores.get)
    sorted_scores = sorted(regime_scores.values(), reverse=True)
    confidence = 60
    if len(sorted_scores) > 1:
        confidence = min(95, 55 + int((sorted_scores[0] - sorted_scores[1]) * 10))

    return {
        "regime": regime,
        "confidence": confidence,
        "scores": regime_scores,
        "drivers": {
            "inflation_yoy": round(float(inflation_ref), 2),
            "growth_proxy": round(float(growth_proxy), 2),
            "unemployment": round(float(unemp), 2),
            "yield_spread_10y_2y": round(float(curve_spread), 2),
        },
    }


def _annualized_downside_deviation(returns):
    if returns.empty:
        return 0.0
    downside = returns[returns < 0]
    if downside.empty:
        return 0.0
    return float(downside.std() * (252 ** 0.5) * 100)


def _max_drawdown_stats(close_series):
    if close_series.empty:
        return {"max_drawdown": 0.0, "peak_date": None, "trough_date": None, "recovery_date": None, "days_to_trough": 0, "days_to_recovery": None, "underwater_days": 0}

    wealth = close_series / close_series.iloc[0]
    running_max = wealth.cummax()
    drawdown = (wealth / running_max) - 1
    trough_date = drawdown.idxmin()
    max_drawdown = float(drawdown.min())
    peak_date = wealth.loc[:trough_date].idxmax()

    recovery_date = None
    post_trough = wealth.loc[trough_date:]
    peak_level = wealth.loc[peak_date]
    recovered = post_trough[post_trough >= peak_level]
    if not recovered.empty:
        recovery_date = recovered.index[0]

    underwater_days = int((drawdown < 0).sum())
    days_to_trough = int((trough_date - peak_date).days) if peak_date is not None else 0
    days_to_recovery = int((recovery_date - trough_date).days) if recovery_date is not None else None

    return {
        "max_drawdown": max_drawdown * 100,
        "peak_date": peak_date,
        "trough_date": trough_date,
        "recovery_date": recovery_date,
        "days_to_trough": days_to_trough,
        "days_to_recovery": days_to_recovery,
        "underwater_days": underwater_days,
    }


def _format_date(value):
    if value is None or pd.isna(value):
        return "N/A"
    return pd.to_datetime(value).strftime("%Y-%m-%d")


def _returns_from_close(close_series):
    if close_series is None or close_series.empty:
        return pd.Series(dtype="float64")
    return close_series.pct_change().dropna()


def _risk_level_from_pct(value, low, medium):
    if value is None:
        return "N/A"
    if value < low:
        return "Low"
    if value < medium:
        return "Moderate"
    return "High"


def compute_crisis_analytics(stock_data, ticker, asset_type, timeline_preset):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return {
            "overview": {},
            "drawdown": {},
            "tail_risk": {},
            "rolling": [],
            "largest_moves": [],
            "event_timeline": [],
            "benchmark": {},
            "heatmap": [],
            "stress_factors": [],
            "scenario_tests": [],
            "phase_returns": [],
            "recovery_ladder": [],
        }

    close = pd.Series(data["Close"], index=pd.to_datetime(data.index), dtype="float64").dropna()
    if close.empty:
        return {
            "overview": {},
            "drawdown": {},
            "tail_risk": {},
            "rolling": [],
            "largest_moves": [],
            "event_timeline": [],
            "benchmark": {},
            "heatmap": [],
            "stress_factors": [],
            "scenario_tests": [],
            "phase_returns": [],
            "recovery_ladder": [],
        }

    returns = _returns_from_close(close)
    drawdown_stats = _max_drawdown_stats(close)
    start = close.index.min()
    end = close.index.max()

    def safe_download_frame(symbol, start_ts, end_ts):
        try:
            frame = yf.download(
                symbol,
                start=start_ts.strftime("%Y-%m-%d"),
                end=(end_ts + pd.Timedelta(days=1)).strftime("%Y-%m-%d"),
                interval="1d",
                progress=False,
            )
            frame = normalize_price_dataframe(frame)
            if frame is None or frame.empty or "Close" not in frame.columns:
                return pd.Series(dtype="float64")
            return pd.Series(frame["Close"], index=pd.to_datetime(frame.index), dtype="float64").dropna()
        except Exception:
            return pd.Series(dtype="float64")

    rolling_vol = returns.rolling(20).std() * (252 ** 0.5) * 100
    rolling_dd = close / close.cummax() - 1
    rolling_tail = returns.rolling(20).quantile(0.05) * 100

    var_95 = float(returns.quantile(0.05) * 100) if not returns.empty else 0.0
    cvar_95 = float(returns[returns <= returns.quantile(0.05)].mean() * 100) if not returns.empty else 0.0
    skew = float(returns.skew()) if not returns.empty else 0.0
    kurt = float(returns.kurt()) if not returns.empty else 0.0

    largest_moves = []
    if not returns.empty:
        for idx, val in returns.sort_values().head(5).items():
            largest_moves.append({"date": idx.strftime("%Y-%m-%d"), "move_pct": round(float(val) * 100, 2), "direction": "Down"})
        for idx, val in returns.sort_values(ascending=False).head(3).items():
            largest_moves.append({"date": idx.strftime("%Y-%m-%d"), "move_pct": round(float(val) * 100, 2), "direction": "Up"})
    largest_moves = sorted(largest_moves, key=lambda x: x["move_pct"])

    if asset_type == "stock":
        benchmark_candidates = ["SPY", "^GSPC", "^DJI"] if start.year >= 1993 else ["^GSPC", "^DJI"]
    elif asset_type == "bond":
        benchmark_candidates = ["BND", "TLT", "^GSPC"] if start.year >= 2003 else ["^GSPC", "^DJI"]
    else:
        benchmark_candidates = ["UUP", "DX-Y.NYB", "^GSPC"] if start.year >= 2007 else ["^GSPC", "^DJI"]

    benchmark_symbol = benchmark_candidates[0]
    bench_close = pd.Series(dtype="float64")
    for candidate in benchmark_candidates:
        candidate_series = safe_download_frame(candidate, start, end)
        if not candidate_series.empty:
            benchmark_symbol = candidate
            bench_close = candidate_series.reindex(close.index).ffill().dropna()
            if not bench_close.empty:
                break

    merged = pd.DataFrame({"asset": close})
    if not bench_close.empty:
        merged["benchmark"] = bench_close
    merged = merged.dropna()

    benchmark = {
        "symbol": benchmark_symbol,
        "asset_return": None,
        "benchmark_return": None,
        "excess_return": None,
        "beta": None,
        "correlation": None,
        "downside_capture": None,
        "rebound_capture": None,
    }

    if not merged.empty and "benchmark" in merged.columns:
        asset_ret = _returns_from_close(merged["asset"])
        bench_ret = _returns_from_close(merged["benchmark"])
        common = pd.concat([asset_ret, bench_ret], axis=1).dropna()
        common.columns = ["asset", "benchmark"]
        if not common.empty:
            covariance = float(common["asset"].cov(common["benchmark"]))
            variance = float(common["benchmark"].var())
            beta = covariance / variance if variance > 0 else None
            corr = float(common["asset"].corr(common["benchmark"]))
            downside = common[common["benchmark"] < 0]
            upside = common[common["benchmark"] > 0]
            downside_capture = None
            rebound_capture = None
            if not downside.empty and abs(float(downside["benchmark"].mean())) > 1e-10:
                downside_capture = float(downside["asset"].mean() / downside["benchmark"].mean())
            if not upside.empty and abs(float(upside["benchmark"].mean())) > 1e-10:
                rebound_capture = float(upside["asset"].mean() / upside["benchmark"].mean())

            benchmark = {
                "symbol": benchmark_symbol,
                "asset_return": round(float((merged["asset"].iloc[-1] / merged["asset"].iloc[0] - 1) * 100), 2),
                "benchmark_return": round(float((merged["benchmark"].iloc[-1] / merged["benchmark"].iloc[0] - 1) * 100), 2),
                "excess_return": round(float((merged["asset"].iloc[-1] / merged["asset"].iloc[0] - merged["benchmark"].iloc[-1] / merged["benchmark"].iloc[0]) * 100), 2),
                "beta": _to_serializable_float(beta, 2),
                "correlation": _to_serializable_float(corr, 2),
                "downside_capture": _to_serializable_float(downside_capture, 2),
                "rebound_capture": _to_serializable_float(rebound_capture, 2),
            }

    total_days = max(1, int((end - start).days))
    phase_edges = [
        start,
        start + pd.Timedelta(days=int(total_days * 0.2)),
        start + pd.Timedelta(days=int(total_days * 0.55)),
        start + pd.Timedelta(days=int(total_days * 0.8)),
        end,
    ]
    phase_labels = ["Pre-Shock", "Shock", "Policy Response", "Recovery"]
    phase_returns = []
    for i, label in enumerate(phase_labels):
        left = phase_edges[i]
        right = phase_edges[i + 1]
        phase_slice = close[(close.index >= left) & (close.index <= right)]
        if phase_slice.empty:
            phase_returns.append({"phase": label, "return_pct": None, "volatility_pct": None})
            continue
        phase_ret = (phase_slice.iloc[-1] / phase_slice.iloc[0] - 1) * 100
        phase_vol = _returns_from_close(phase_slice).std() * (252 ** 0.5) * 100
        phase_returns.append({
            "phase": label,
            "return_pct": round(float(phase_ret), 2),
            "volatility_pct": round(float(phase_vol), 2) if not pd.isna(phase_vol) else None,
        })

    trough = drawdown_stats.get("trough_date")
    recovery_ladder = []
    if trough is not None:
        peak_price = close.loc[drawdown_stats["peak_date"]] if drawdown_stats.get("peak_date") in close.index else close.max()
        trough_price = close.loc[trough]
        gap = float(peak_price - trough_price)
        for pct in [0.25, 0.5, 0.75, 1.0]:
            target = trough_price + gap * pct
            segment = close.loc[trough:]
            hit = segment[segment >= target]
            recovery_ladder.append({
                "level": f"{int(pct * 100)}%",
                "target_price": round(float(target), 2),
                "hit_date": _format_date(hit.index[0] if not hit.empty else None),
                "days": int((hit.index[0] - trough).days) if not hit.empty else None,
            })

    stress_series_map = {
        "VIX": "^VIX",
        "HY Spread": "BAMLH0A0HYM2",
        "IG Spread": "BAMLC0A0CM",
        "US 10Y": "DGS10",
        "US 2Y": "DGS2",
    }
    stress_factors = []
    for label, code in stress_series_map.items():
        try:
            if code.startswith("^"):
                if code == "^VIX" and start.year < 1990:
                    continue
                ser = safe_download_frame(code, start, end).reindex(close.index).ffill().dropna()
            else:
                ser = fetch_fred_series(code, start, end).reindex(close.index).ffill().dropna()
            if ser.empty:
                continue
            stress_factors.append({
                "factor": label,
                "start": _to_serializable_float(ser.iloc[0], 2),
                "end": _to_serializable_float(ser.iloc[-1], 2),
                "avg": _to_serializable_float(ser.mean(), 2),
                "max": _to_serializable_float(ser.max(), 2),
                "change": _to_serializable_float(ser.iloc[-1] - ser.iloc[0], 2),
            })
        except Exception:
            continue

    crisis_meta = CRISIS_PRESET_LIBRARY.get(timeline_preset, {})
    event_timeline = [{"date": d, "event": e} for d, e in crisis_meta.get("events", [])]

    scenario_tests = []
    if not close.empty:
        buy_hold = (close.iloc[-1] / close.iloc[0] - 1) * 100
        scenario_tests.append({"strategy": "Lump Sum at Start", "return_pct": round(float(buy_hold), 2)})

        monthly = close.resample("MS").first().dropna()
        if len(monthly) >= 2:
            units = float((1.0 / monthly).sum())
            final_value = units * float(close.iloc[-1])
            invested = float(len(monthly))
            dca_ret = ((final_value / invested) - 1) * 100
            scenario_tests.append({"strategy": "Monthly DCA", "return_pct": round(float(dca_ret), 2)})

        rolling_high = close.cummax()
        drawdown = close / rolling_high - 1
        stop_hits = int((drawdown <= -0.1).sum())
        scenario_tests.append({"strategy": "10% Drawdown Stop Trigger Days", "return_pct": -stop_hits})

    if start.year < 1993:
        heatmap_symbols = ["^DJI", "^GSPC", "^IXIC"]
    elif start.year < 2003:
        heatmap_symbols = ["^GSPC", "^IXIC", "^DJI", "QQQ"]
    else:
        heatmap_symbols = ["SPY", "QQQ", "XLF", "XLE", "XLV", "TLT", "GLD"]
    heatmap = []
    for symbol in heatmap_symbols:
        try:
            s = safe_download_frame(symbol, start, end)
            if s.empty:
                continue
            ret = (s.iloc[-1] / s.iloc[0] - 1) * 100
            vol = _returns_from_close(s).std() * (252 ** 0.5) * 100
            heatmap.append({"symbol": symbol, "return_pct": round(float(ret), 2), "volatility_pct": round(float(vol), 2) if not pd.isna(vol) else None})
        except Exception:
            continue

    rolling_rows = []
    if not returns.empty:
        dates = returns.index
        bench_returns = pd.Series(dtype="float64")
        if not merged.empty and "benchmark" in merged.columns:
            bench_returns = _returns_from_close(merged["benchmark"]).reindex(dates)
        rolling_beta = pd.Series(index=dates, dtype="float64")
        if not bench_returns.empty:
            cov = returns.rolling(20).cov(bench_returns)
            var = bench_returns.rolling(20).var()
            rolling_beta = cov / var.replace(0, np.nan)
        rolling_corr = returns.rolling(20).corr(bench_returns) if not bench_returns.empty else pd.Series(index=dates, dtype="float64")
        downside_roll = returns.rolling(20).apply(lambda x: np.std(np.minimum(x, 0)) * (252 ** 0.5) * 100 if len(x) else np.nan)

        for dt in dates[-80:]:
            rolling_rows.append({
                "date": dt.strftime("%Y-%m-%d"),
                "roll_vol": _to_serializable_float(rolling_vol.reindex(dates).loc[dt], 2),
                "roll_dd": _to_serializable_float((rolling_dd.reindex(close.index).ffill().loc[dt] if dt in rolling_dd.index else np.nan) * 100, 2),
                "roll_tail": _to_serializable_float(rolling_tail.reindex(dates).loc[dt], 2),
                "roll_beta": _to_serializable_float(rolling_beta.reindex(dates).loc[dt], 2),
                "roll_corr": _to_serializable_float(rolling_corr.reindex(dates).loc[dt], 2),
                "downside_dev": _to_serializable_float(downside_roll.reindex(dates).loc[dt], 2),
            })

    overview = {
        "window_start": _format_date(close.index.min()),
        "window_end": _format_date(close.index.max()),
        "sessions": int(len(close)),
        "return_pct": round(float((close.iloc[-1] / close.iloc[0] - 1) * 100), 2),
        "annualized_vol_pct": round(float((returns.std() * (252 ** 0.5) * 100) if not returns.empty else 0), 2),
        "downside_dev_pct": round(float(_annualized_downside_deviation(returns)), 2),
        "largest_down_day_pct": round(float(returns.min() * 100), 2) if not returns.empty else None,
        "largest_up_day_pct": round(float(returns.max() * 100), 2) if not returns.empty else None,
        "risk_level": _risk_level_from_pct(abs(drawdown_stats["max_drawdown"]), 15, 35),
    }

    drawdown_payload = {
        "max_drawdown_pct": round(float(drawdown_stats["max_drawdown"]), 2),
        "peak_date": _format_date(drawdown_stats["peak_date"]),
        "trough_date": _format_date(drawdown_stats["trough_date"]),
        "recovery_date": _format_date(drawdown_stats["recovery_date"]),
        "days_to_trough": drawdown_stats["days_to_trough"],
        "days_to_recovery": drawdown_stats["days_to_recovery"],
        "underwater_days": drawdown_stats["underwater_days"],
    }

    tail_risk = {
        "var_95_pct": round(var_95, 2),
        "cvar_95_pct": round(cvar_95, 2),
        "skew": round(skew, 3),
        "kurtosis": round(kurt, 3),
    }

    return {
        "overview": overview,
        "drawdown": drawdown_payload,
        "tail_risk": tail_risk,
        "rolling": rolling_rows,
        "largest_moves": largest_moves,
        "event_timeline": event_timeline,
        "benchmark": benchmark,
        "heatmap": heatmap,
        "stress_factors": stress_factors,
        "scenario_tests": scenario_tests,
        "phase_returns": phase_returns,
        "recovery_ladder": recovery_ladder,
    }


def parse_csv_values(value):
    if not value:
        return []
    return [item.strip().lower() for item in value.split(",") if item.strip()]


def compute_indicator_series(stock_data):
    stock_data = normalize_price_dataframe(stock_data).copy()
    if stock_data.empty:
        return {}

    close = pd.Series(stock_data["Close"], index=stock_data.index, dtype="float64")
    high = pd.Series(stock_data["High"], index=stock_data.index, dtype="float64")
    low = pd.Series(stock_data["Low"], index=stock_data.index, dtype="float64")
    volume = pd.Series(stock_data["Volume"], index=stock_data.index, dtype="float64") if "Volume" in stock_data.columns else pd.Series(0.0, index=stock_data.index)

    indicators = {}
    indicators["sma10"] = close.rolling(window=10).mean()
    indicators["sma20"] = close.rolling(window=20).mean()
    indicators["sma50"] = close.rolling(window=50).mean()
    indicators["sma100"] = close.rolling(window=100).mean()
    indicators["sma200"] = close.rolling(window=200).mean()
    indicators["ema9"] = close.ewm(span=9, adjust=False).mean()
    indicators["ema20"] = close.ewm(span=20, adjust=False).mean()
    indicators["ema21"] = close.ewm(span=21, adjust=False).mean()
    indicators["ema50"] = close.ewm(span=50, adjust=False).mean()
    indicators["ema100"] = close.ewm(span=100, adjust=False).mean()
    indicators["wma20"] = close.rolling(window=20).apply(
        lambda x: float((x * pd.Series(range(1, 21), index=x.index, dtype="float64")).sum() / 210),
        raw=False,
    )
    indicators["hma20"] = (2 * close.rolling(window=10).mean() - close.rolling(window=20).mean()).rolling(window=4).mean()
    indicators["vwma20"] = (close * volume).rolling(window=20).sum() / volume.rolling(window=20).sum().replace(0, pd.NA)

    delta = close.diff()
    gain = delta.clip(lower=0)
    loss = -delta.clip(upper=0)
    avg_gain = gain.rolling(window=14).mean()
    avg_loss = loss.rolling(window=14).mean()
    avg_loss = avg_loss.mask(avg_loss == 0)
    rs = avg_gain / avg_loss
    indicators["rsi14"] = 100 - (100 / (1 + rs))
    rsi2_gain = gain.rolling(window=2).mean()
    rsi2_loss = loss.rolling(window=2).mean().replace(0, pd.NA)
    indicators["rsi2"] = 100 - (100 / (1 + (rsi2_gain / rsi2_loss)))
    rsi21_gain = gain.rolling(window=21).mean()
    rsi21_loss = loss.rolling(window=21).mean().replace(0, pd.NA)
    indicators["rsi21"] = 100 - (100 / (1 + (rsi21_gain / rsi21_loss)))

    ema12 = close.ewm(span=12, adjust=False).mean()
    ema26 = close.ewm(span=26, adjust=False).mean()
    macd_line = ema12 - ema26
    signal_line = macd_line.ewm(span=9, adjust=False).mean()
    indicators["macd"] = macd_line
    indicators["macd_signal"] = signal_line
    indicators["macd_hist"] = macd_line - signal_line
    ppo = ((ema12 - ema26) / ema26.replace(0, pd.NA)) * 100
    ppo_signal = ppo.ewm(span=9, adjust=False).mean()
    indicators["ppo"] = ppo
    indicators["ppo_signal"] = ppo_signal
    indicators["ppo_hist"] = ppo - ppo_signal
    trix_ema1 = close.ewm(span=15, adjust=False).mean()
    trix_ema2 = trix_ema1.ewm(span=15, adjust=False).mean()
    trix_ema3 = trix_ema2.ewm(span=15, adjust=False).mean()
    indicators["trix15"] = (trix_ema3 / trix_ema3.shift(1) - 1) * 100

    bb_mid = close.rolling(window=20).mean()
    bb_std = close.rolling(window=20).std()
    indicators["bbands_mid"] = bb_mid
    indicators["bbands_upper"] = bb_mid + (2 * bb_std)
    indicators["bbands_lower"] = bb_mid - (2 * bb_std)
    indicators["bbands_width"] = (indicators["bbands_upper"] - indicators["bbands_lower"]) / bb_mid.replace(0, pd.NA)

    prev_close = close.shift(1)
    tr_components = pd.concat([
        (high - low),
        (high - prev_close).abs(),
        (low - prev_close).abs(),
    ], axis=1)
    true_range = tr_components.max(axis=1)
    indicators["atr14"] = true_range.rolling(window=14).mean()

    low14 = low.rolling(window=14).min()
    high14 = high.rolling(window=14).max()
    high_low_diff = high14 - low14
    high_low_diff = high_low_diff.mask(high_low_diff == 0)
    stoch_k = ((close - low14) / high_low_diff) * 100
    indicators["stoch_k"] = stoch_k
    indicators["stoch_d"] = stoch_k.rolling(window=3).mean()
    rsi_min = indicators["rsi14"].rolling(window=14).min()
    rsi_max = indicators["rsi14"].rolling(window=14).max()
    stoch_rsi = ((indicators["rsi14"] - rsi_min) / (rsi_max - rsi_min).replace(0, pd.NA)) * 100
    indicators["stochrsi_k"] = stoch_rsi
    indicators["stochrsi_d"] = stoch_rsi.rolling(window=3).mean()

    direction = close.diff().fillna(0)
    obv_step = pd.Series(0, index=close.index)
    obv_step[direction > 0] = volume[direction > 0]
    obv_step[direction < 0] = -volume[direction < 0]
    indicators["obv"] = obv_step.cumsum()

    typical_price = (high + low + close) / 3
    cumulative_volume = volume.mask(volume == 0).cumsum()
    indicators["vwap"] = (typical_price * volume).cumsum() / cumulative_volume

    plus_dm = high.diff()
    minus_dm = low.diff() * -1
    plus_dm = plus_dm.where((plus_dm > minus_dm) & (plus_dm > 0), 0.0)
    minus_dm = minus_dm.where((minus_dm > plus_dm) & (minus_dm > 0), 0.0)
    tr14 = true_range.rolling(window=14).sum()
    tr14 = tr14.mask(tr14 == 0)
    plus_di = 100 * (plus_dm.rolling(window=14).sum() / tr14)
    minus_di = 100 * (minus_dm.rolling(window=14).sum() / tr14)
    dx = ((plus_di - minus_di).abs() / (plus_di + minus_di).replace(0, pd.NA)) * 100
    indicators["adx"] = dx.rolling(window=14).mean()
    indicators["plus_di"] = plus_di
    indicators["minus_di"] = minus_di

    indicators["roc12"] = (close / close.shift(12) - 1) * 100
    indicators["mom10"] = close - close.shift(10)
    wr_div = (high14 - low14)
    wr_div = wr_div.mask(wr_div == 0)
    indicators["williamsr14"] = -100 * ((high14 - close) / wr_div)
    typical = (high + low + close) / 3
    sma_typical = typical.rolling(window=20).mean()
    mad = (typical - sma_typical).abs().rolling(window=20).mean().replace(0, pd.NA)
    indicators["cci20"] = (typical - sma_typical) / (0.015 * mad)

    money_flow_raw = typical * volume
    positive_flow = money_flow_raw.where(typical > typical.shift(1), 0.0)
    negative_flow = money_flow_raw.where(typical < typical.shift(1), 0.0)
    mfr = positive_flow.rolling(window=14).sum() / negative_flow.rolling(window=14).sum().replace(0, pd.NA)
    indicators["mfi14"] = 100 - (100 / (1 + mfr))

    mf_multiplier = ((close - low) - (high - close)) / (high - low).replace(0, pd.NA)
    mf_volume = mf_multiplier * volume
    vol20 = volume.rolling(window=20).sum()
    vol20 = vol20.mask(vol20 == 0)
    indicators["cmf20"] = mf_volume.rolling(window=20).sum() / vol20
    adl = mf_volume.cumsum()
    indicators["adl"] = adl
    indicators["chaikinosc"] = adl.ewm(span=3, adjust=False).mean() - adl.ewm(span=10, adjust=False).mean()
    indicators["forceindex13"] = (close - close.shift(1)) * volume
    indicators["dpo20"] = close.shift(int(20 / 2) + 1) - close.rolling(window=20).mean()
    indicators["hv20"] = close.pct_change().rolling(window=20).std() * (252 ** 0.5) * 100
    indicators["ultimateosc"] = (
        4 * (((close - low.combine(close.shift(1), max)) / (high.combine(close.shift(1), max) - low.combine(close.shift(1), min)).replace(0, pd.NA)).rolling(7).sum()) +
        2 * (((close - low.combine(close.shift(1), max)) / (high.combine(close.shift(1), max) - low.combine(close.shift(1), min)).replace(0, pd.NA)).rolling(14).sum()) +
        (((close - low.combine(close.shift(1), max)) / (high.combine(close.shift(1), max) - low.combine(close.shift(1), min)).replace(0, pd.NA)).rolling(28).sum())
    ) / 7 * 100
    aroon_up = high.rolling(window=25).apply(lambda s: ((24 - (24 - s.argmax())) / 24) * 100, raw=True)
    aroon_down = low.rolling(window=25).apply(lambda s: ((24 - (24 - s.argmin())) / 24) * 100, raw=True)
    indicators["aroon_up"] = aroon_up
    indicators["aroon_down"] = aroon_down

    indicators["donchian_upper"] = high.rolling(window=20).max()
    indicators["donchian_lower"] = low.rolling(window=20).min()
    indicators["donchian_mid"] = (indicators["donchian_upper"] + indicators["donchian_lower"]) / 2

    keltner_mid = close.ewm(span=20, adjust=False).mean()
    keltner_range = true_range.rolling(window=20).mean()
    indicators["keltner_mid"] = keltner_mid
    indicators["keltner_upper"] = keltner_mid + (2 * keltner_range)
    indicators["keltner_lower"] = keltner_mid - (2 * keltner_range)

    hl2 = (high + low) / 2
    atr10 = true_range.rolling(window=10).mean()
    supertrend_upper = hl2 + (3 * atr10)
    supertrend_lower = hl2 - (3 * atr10)
    supertrend = pd.Series(index=close.index, dtype="float64")
    direction_flag = pd.Series(index=close.index, dtype="float64")
    for i in range(len(close)):
        if i == 0:
            supertrend.iloc[i] = close.iloc[i]
            direction_flag.iloc[i] = 1
            continue
        prev_st = supertrend.iloc[i - 1]
        if close.iloc[i] > prev_st:
            direction_flag.iloc[i] = 1
        elif close.iloc[i] < prev_st:
            direction_flag.iloc[i] = -1
        else:
            direction_flag.iloc[i] = direction_flag.iloc[i - 1]
        supertrend.iloc[i] = supertrend_lower.iloc[i] if direction_flag.iloc[i] == 1 else supertrend_upper.iloc[i]

    indicators["supertrend"] = supertrend
    indicators["supertrend_dir"] = direction_flag

    sar = close.copy()
    sar[:] = pd.NA
    if len(close) > 2:
        bull = True
        af = 0.02
        ep = high.iloc[0]
        sar.iloc[0] = low.iloc[0]
        for i in range(1, len(close)):
            prev_sar = sar.iloc[i - 1]
            sar.iloc[i] = prev_sar + af * (ep - prev_sar)
            if bull:
                sar.iloc[i] = min(sar.iloc[i], low.iloc[i - 1])
                if close.iloc[i] < sar.iloc[i]:
                    bull = False
                    sar.iloc[i] = ep
                    ep = low.iloc[i]
                    af = 0.02
                else:
                    if high.iloc[i] > ep:
                        ep = high.iloc[i]
                        af = min(0.2, af + 0.02)
            else:
                sar.iloc[i] = max(sar.iloc[i], high.iloc[i - 1])
                if close.iloc[i] > sar.iloc[i]:
                    bull = True
                    sar.iloc[i] = ep
                    ep = high.iloc[i]
                    af = 0.02
                else:
                    if low.iloc[i] < ep:
                        ep = low.iloc[i]
                        af = min(0.2, af + 0.02)
    indicators["psar"] = sar

    nine_high = high.rolling(window=9).max()
    nine_low = low.rolling(window=9).min()
    indicators["ichimoku_tenkan"] = (nine_high + nine_low) / 2
    twenty_six_high = high.rolling(window=26).max()
    twenty_six_low = low.rolling(window=26).min()
    kijun = (twenty_six_high + twenty_six_low) / 2
    indicators["ichimoku_kijun"] = kijun
    indicators["ichimoku_senkou_a"] = ((indicators["ichimoku_tenkan"] + kijun) / 2).shift(26)
    fifty_two_high = high.rolling(window=52).max()
    fifty_two_low = low.rolling(window=52).min()
    indicators["ichimoku_senkou_b"] = ((fifty_two_high + fifty_two_low) / 2).shift(26)
    indicators["ichimoku_chikou"] = close.shift(-26)

    return indicators


def fetch_fred_series(series_id, start_date, end_date):
    url = f"https://fred.stlouisfed.org/graph/fredgraph.csv?id={series_id}"
    response = requests.get(url, timeout=20)
    response.raise_for_status()

    frame = pd.read_csv(StringIO(response.text))
    if "DATE" not in frame.columns or series_id not in frame.columns:
        return pd.Series(dtype=float)

    frame["DATE"] = pd.to_datetime(frame["DATE"], errors="coerce")
    frame[series_id] = pd.to_numeric(frame[series_id], errors="coerce")
    frame = frame.dropna(subset=["DATE"]).set_index("DATE").sort_index()
    series = frame[series_id]

    if start_date is not None:
        series = series[series.index >= start_date]
    if end_date is not None:
        series = series[series.index <= end_date]
    return series


def fetch_macro_overlay_series(overlays, stock_index):
    if len(stock_index) == 0:
        return {}

    start_date = pd.to_datetime(stock_index.min())
    end_date = pd.to_datetime(stock_index.max())
    result = {}

    if "vix" in overlays:
        vix = yf.download("^VIX", start=start_date.strftime("%Y-%m-%d"), end=(end_date + pd.Timedelta(days=1)).strftime("%Y-%m-%d"), interval="1d")
        vix = normalize_price_dataframe(vix)
        if not vix.empty and "Close" in vix.columns:
            result["vix"] = vix["Close"].reindex(stock_index).ffill()

    fred_map = {
        "credit_spread_hy": "BAMLH0A0HYM2",
        "credit_spread_ig": "BAMLC0A0CM",
        "yield_2y": "DGS2",
        "yield_10y": "DGS10",
        "breakeven_10y": "T10YIE",
    }

    fetched = {}
    for overlay in overlays:
        if overlay in fred_map:
            try:
                series = fetch_fred_series(fred_map[overlay], start_date, end_date)
                fetched[overlay] = series.reindex(stock_index).ffill()
            except Exception:
                fetched[overlay] = pd.Series(dtype=float)

    result.update({k: v for k, v in fetched.items() if not v.empty})
    if "yield_curve_spread" in overlays and "yield_10y" in fetched and "yield_2y" in fetched:
        spread = fetched["yield_10y"].reindex(stock_index).ffill() - fetched["yield_2y"].reindex(stock_index).ffill()
        result["yield_curve_spread"] = spread

    return result


def safe_float(value, default=0.0):
    try:
        if value is None or pd.isna(value):
            return default
        return float(value)
    except Exception:
        return default


def latest_value_from_fred(series_id):
    try:
        series = fetch_fred_series(series_id, None, None)
        if series.empty:
            return None
        return safe_float(series.dropna().iloc[-1], None)
    except Exception:
        return None


def trailing_mean_from_fred(series_id, periods=6):
    try:
        series = fetch_fred_series(series_id, None, None)
        if series.empty:
            return None
        clean = series.dropna().tail(periods)
        if clean.empty:
            return None
        return safe_float(clean.mean(), None)
    except Exception:
        return None


def compute_macro_regime_classifier():
    cpi = fetch_fred_series("CPIAUCSL", None, None)
    inflation_yoy = None
    if not cpi.empty and len(cpi.dropna()) > 13:
        inflation_yoy = safe_float(((cpi.dropna().iloc[-1] / cpi.dropna().iloc[-13]) - 1) * 100, None)

    unemp = latest_value_from_fred("UNRATE")
    unemp_6m = trailing_mean_from_fred("UNRATE", 6)
    curve_spread = None
    y10 = latest_value_from_fred("DGS10")
    y2 = latest_value_from_fred("DGS2")
    if y10 is not None and y2 is not None:
        curve_spread = y10 - y2

    gdp = fetch_fred_series("GDPC1", None, None)
    growth_proxy = None
    if not gdp.empty and len(gdp.dropna()) > 4:
        gdp_clean = gdp.dropna()
        growth_proxy = safe_float(((gdp_clean.iloc[-1] / gdp_clean.iloc[-5]) - 1) * 100, None)

    pce = latest_value_from_fred("PCEPI")
    pce_yoy = None
    pce_series = fetch_fred_series("PCEPI", None, None)
    if not pce_series.empty and len(pce_series.dropna()) > 13:
        ps = pce_series.dropna()
        pce_yoy = safe_float(((ps.iloc[-1] / ps.iloc[-13]) - 1) * 100, None)

    score_expansion = 0
    score_recession = 0
    score_overheating = 0
    score_stagflation = 0

    inflation_ref = inflation_yoy if inflation_yoy is not None else pce_yoy
    if inflation_ref is None:
        inflation_ref = 2.5
    if growth_proxy is None:
        growth_proxy = 1.5
    if unemp is None:
        unemp = 4.5
    if unemp_6m is None:
        unemp_6m = unemp
    if curve_spread is None:
        curve_spread = 0.2

    if growth_proxy > 1.5 and inflation_ref < 3.5 and unemp <= 4.5:
        score_expansion += 3
    if growth_proxy < 0.8 or unemp > 5.2 or curve_spread < -0.2:
        score_recession += 3
    if growth_proxy > 2.0 and inflation_ref >= 3.5 and unemp < 4.2:
        score_overheating += 3
    if inflation_ref >= 3.5 and growth_proxy < 1.2 and unemp >= unemp_6m:
        score_stagflation += 4

    if curve_spread > 0.4:
        score_expansion += 1
    if curve_spread < 0:
        score_recession += 1
        score_stagflation += 1

    if inflation_ref > 4.2:
        score_overheating += 1
        score_stagflation += 1

    regime_scores = {
        "Expansion": score_expansion,
        "Recession": score_recession,
        "Overheating": score_overheating,
        "Stagflation": score_stagflation,
    }
    regime = max(regime_scores, key=regime_scores.get)
    sorted_scores = sorted(regime_scores.values(), reverse=True)
    confidence = 60
    if len(sorted_scores) > 1:
        confidence = min(95, 55 + int((sorted_scores[0] - sorted_scores[1]) * 10))

    return {
        "regime": regime,
        "confidence": confidence,
        "scores": regime_scores,
        "drivers": {
            "inflation_yoy": round(inflation_ref, 2),
            "growth_proxy": round(growth_proxy, 2),
            "unemployment": round(unemp, 2),
            "yield_spread_10y_2y": round(curve_spread, 2),
        },
    }


def score_single_stock_for_regime(ticker, regime):
    try:
        data = yf.download(ticker, period="6mo", interval="1d")
        data = normalize_price_dataframe(data)
        if data.empty or "Close" not in data.columns:
            return {"score": 50, "bias": "Neutral"}

        close = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
        volume = pd.Series(data["Volume"], index=data.index, dtype="float64").dropna() if "Volume" in data.columns else pd.Series(dtype="float64")
        if close.empty:
            return {"score": 50, "bias": "Neutral"}

        ret_21 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 22)]) - 1, 0) * 100 if len(close) > 22 else 0
        ret_63 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 64)]) - 1, 0) * 100 if len(close) > 64 else ret_21
        vol_ratio = 1.0
        if not volume.empty and len(volume) > 40:
            vol_ratio = safe_float(volume.tail(10).mean() / max(volume.tail(40).mean(), 1), 1.0)

        base = 50 + (ret_21 * 0.6) + (ret_63 * 0.25) + ((vol_ratio - 1) * 10)
        if regime == "Expansion":
            base += max(0, ret_21) * 0.25
        elif regime == "Recession":
            base -= max(0, -ret_21) * 0.15
        elif regime == "Overheating":
            base += max(0, ret_21) * 0.1
        elif regime == "Stagflation":
            base -= abs(ret_21) * 0.05

        score = int(max(0, min(100, round(base))))
        bias = "Bullish" if score >= 65 else "Neutral" if score >= 45 else "Defensive"
        return {"score": score, "bias": bias, "ret_1m": round(ret_21, 2), "ret_3m": round(ret_63, 2), "vol_ratio": round(vol_ratio, 2)}
    except Exception:
        return {"score": 50, "bias": "Neutral"}


def score_bond_for_regime(stock_data, regime):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return {"score": 50, "bias": "Neutral"}

    close = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
    if close.empty:
        return {"score": 50, "bias": "Neutral"}

    ret_21 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 22)]) - 1, 0) * 100 if len(close) > 22 else 0
    ret_63 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 64)]) - 1, 0) * 100 if len(close) > 64 else ret_21
    returns = close.pct_change().dropna()
    vol = float(returns.std() * (252 ** 0.5) * 100) if not returns.empty else 0

    base = 55 + (ret_21 * 0.5) + (ret_63 * 0.2) - (vol * 0.35)
    if regime == "Recession":
        base += 5
    elif regime == "Overheating":
        base -= 4
    elif regime == "Stagflation":
        base -= 2

    score = int(max(0, min(100, round(base))))
    bias = "Defensive" if score >= 62 else "Neutral" if score >= 45 else "Rate-Sensitive"
    return {"score": score, "bias": bias, "ret_1m": round(ret_21, 2), "ret_3m": round(ret_63, 2), "vol_ratio": round(vol, 2)}


def _bond_benchmark_for_symbol(symbol):
    s = (symbol or "").upper()
    if s in {"TLT", "TLH", "UST20Y", "UST30Y", "UST10Y"}:
        return "TLT"
    if s in {"SHY", "VGSH", "SCHO", "UST2Y", "UST3Y", "UST5Y"}:
        return "IEF"
    if s in {"LQD", "VCIT", "IGIB"}:
        return "LQD"
    if s in {"HYG", "JNK", "SJNK", "USHY"}:
        return "HYG"
    return "BND"


def _download_close_series(symbol, start, end):
    if symbol in TREASURY_NODE_MAP:
        frame = fetch_treasury_node_data(symbol, period="1y", start_date=start.strftime("%Y-%m-%d"), end_date=end.strftime("%Y-%m-%d"))
    else:
        frame = yf.download(symbol, start=start.strftime("%Y-%m-%d"), end=(end + pd.Timedelta(days=1)).strftime("%Y-%m-%d"), interval="1d")
    frame = normalize_price_dataframe(frame)
    if frame is None or frame.empty or "Close" not in frame.columns:
        return pd.Series(dtype="float64")
    return pd.Series(frame["Close"], index=pd.to_datetime(frame.index), dtype="float64").dropna()


def compute_bond_metrics(stock_data, ticker, timeline_preset, is_crisis_mode):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return None

    close = pd.Series(data["Close"], index=pd.to_datetime(data.index), dtype="float64").dropna()
    volume = pd.Series(data["Volume"], index=close.index, dtype="float64").fillna(0) if "Volume" in data.columns else pd.Series(0.0, index=close.index)
    if close.empty:
        return None

    start = close.index.min()
    end = close.index.max()
    returns = close.pct_change().dropna()
    benchmark_symbol = _bond_benchmark_for_symbol(ticker)
    benchmark_close = _download_close_series(benchmark_symbol, start, end).reindex(close.index).ffill().dropna()

    y2 = fetch_fred_series("DGS2", start, end).reindex(close.index).ffill()
    y5 = fetch_fred_series("DGS5", start, end).reindex(close.index).ffill()
    y10 = fetch_fred_series("DGS10", start, end).reindex(close.index).ffill()
    y30 = fetch_fred_series("DGS30", start, end).reindex(close.index).ffill()
    hy = fetch_fred_series("BAMLH0A0HYM2", start, end).reindex(close.index).ffill()
    ig = fetch_fred_series("BAMLC0A0CM", start, end).reindex(close.index).ffill()
    be10 = fetch_fred_series("T10YIE", start, end).reindex(close.index).ffill()

    dgs10_change = y10.diff().dropna()
    asset_ret = returns.reindex(dgs10_change.index).dropna()
    common = pd.concat([asset_ret, dgs10_change.reindex(asset_ret.index)], axis=1).dropna()
    common.columns = ["asset", "dgs10_change"]
    duration_proxy = None
    dv01_proxy = None
    if not common.empty:
        x = common["dgs10_change"]
        y = common["asset"]
        varx = float(x.var())
        if varx > 0:
            beta_rate = float(y.cov(x) / varx)
            duration_proxy = round(abs(beta_rate) * 100, 2)
            dv01_proxy = round(beta_rate / 10000, 8)

    spread_change = (hy - ig).dropna()
    spread_beta = None
    if not spread_change.empty and not returns.empty:
        rr = returns.reindex(spread_change.index)
        c2 = pd.concat([rr, spread_change], axis=1).dropna()
        if not c2.empty and float(c2.iloc[:, 1].var()) > 0:
            spread_beta = float(c2.iloc[:, 0].cov(c2.iloc[:, 1]) / c2.iloc[:, 1].var())

    drawdown = (close / close.cummax() - 1)
    max_dd = float(drawdown.min() * 100) if not drawdown.empty else 0
    underwater_days = int((drawdown < 0).sum())
    volatility = float(returns.std() * (252 ** 0.5) * 100) if not returns.empty else 0
    downside_dev = _annualized_downside_deviation(returns)

    curve_2s10s = (y10 - y2).dropna()
    curve_5s30s = (y30 - y5).dropna()
    curve_regime = "Flat"
    if not curve_2s10s.empty:
        latest = float(curve_2s10s.iloc[-1])
        prev = float(curve_2s10s.iloc[max(0, len(curve_2s10s) - 22)])
        if latest < 0:
            curve_regime = "Inverted"
        elif latest - prev > 0.2:
            curve_regime = "Steepening"
        elif latest - prev < -0.2:
            curve_regime = "Flattening"
        else:
            curve_regime = "Stable"

    carry_proxy = None
    roll_proxy = None
    if not y10.dropna().empty:
        carry_proxy = float(y10.dropna().iloc[-1])
        if not curve_2s10s.empty:
            roll_proxy = float(curve_2s10s.iloc[-1]) * 0.2

    gap_count = int(((close / close.shift(1) - 1).abs() > 0.02).sum()) if len(close) > 1 else 0
    vol_impulse = float(volume.tail(10).mean() / max(volume.tail(40).mean(), 1)) if len(volume) > 40 else 1.0
    stress_day_freq = float(((returns.abs() > returns.abs().quantile(0.9)).sum() / max(1, len(returns))) * 100) if not returns.empty else 0

    benchmark_stats = {
        "symbol": benchmark_symbol,
        "asset_return": round(float((close.iloc[-1] / close.iloc[0] - 1) * 100), 2),
        "benchmark_return": None,
        "excess_return": None,
    }
    if not benchmark_close.empty:
        bret = float((benchmark_close.iloc[-1] / benchmark_close.iloc[0] - 1) * 100)
        benchmark_stats["benchmark_return"] = round(bret, 2)
        benchmark_stats["excess_return"] = round(benchmark_stats["asset_return"] - bret, 2)

    return {
        "overview": {
            "return_pct": benchmark_stats["asset_return"],
            "volatility_pct": round(volatility, 2),
            "downside_dev_pct": round(float(downside_dev), 2),
            "max_drawdown_pct": round(max_dd, 2),
            "underwater_days": underwater_days,
        },
        "rates": {
            "duration_proxy": duration_proxy,
            "dv01_proxy": dv01_proxy,
            "y2": _to_serializable_float(y2.dropna().iloc[-1] if not y2.dropna().empty else None, 2),
            "y10": _to_serializable_float(y10.dropna().iloc[-1] if not y10.dropna().empty else None, 2),
            "y30": _to_serializable_float(y30.dropna().iloc[-1] if not y30.dropna().empty else None, 2),
        },
        "curve": {
            "curve_2s10s": _to_serializable_float(curve_2s10s.iloc[-1] if not curve_2s10s.empty else None, 2),
            "curve_5s30s": _to_serializable_float(curve_5s30s.iloc[-1] if not curve_5s30s.empty else None, 2),
            "regime": curve_regime,
            "inversion_depth": _to_serializable_float(curve_2s10s.min() if not curve_2s10s.empty else None, 2),
        },
        "credit": {
            "hy_spread": _to_serializable_float(hy.dropna().iloc[-1] if not hy.dropna().empty else None, 2),
            "ig_spread": _to_serializable_float(ig.dropna().iloc[-1] if not ig.dropna().empty else None, 2),
            "hy_ig_diff": _to_serializable_float((hy - ig).dropna().iloc[-1] if not (hy - ig).dropna().empty else None, 2),
            "spread_beta": _to_serializable_float(spread_beta, 3),
        },
        "inflation": {
            "breakeven_10y": _to_serializable_float(be10.dropna().iloc[-1] if not be10.dropna().empty else None, 2),
            "breakeven_change": _to_serializable_float((be10.dropna().iloc[-1] - be10.dropna().iloc[0]) if len(be10.dropna()) > 1 else None, 2),
        },
        "carry_roll": {
            "carry_proxy": _to_serializable_float(carry_proxy, 2),
            "roll_proxy": _to_serializable_float(roll_proxy, 2),
        },
        "liquidity": {
            "volume_impulse": round(vol_impulse, 2),
            "gap_count": gap_count,
            "stress_day_freq": round(stress_day_freq, 2),
        },
        "benchmark": benchmark_stats,
        "instrument_type": "Treasury Node" if ticker in TREASURY_NODE_MAP else "Bond ETF/Proxy",
        "is_crisis_mode": is_crisis_mode,
    }


def build_regime_watchlist(regime, asset_type="stock", period="1y", start_date=None, end_date=None):
    if asset_type == "forex":
        universe = [
            "EURUSD=X", "USDJPY=X", "GBPUSD=X", "AUDUSD=X", "USDCAD=X", "USDCHF=X",
            "NZDUSD=X", "EURJPY=X", "EURGBP=X", "EURCHF=X", "EURAUD=X", "GBPJPY=X",
        ]
    elif asset_type == "bond":
        universe = BOND_PROXY_UNIVERSE + list(TREASURY_NODE_MAP.keys())
    else:
        universe = [
            "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL", "META", "TSLA", "JPM", "XOM", "LLY",
            "AVGO", "AMD", "NFLX", "CRM", "UBER", "ORCL", "BAC", "V", "MA", "SPY",
        ]
    def fetch_window(symbol):
        if asset_type == "bond":
            if start_date is not None and end_date is not None:
                return fetch_treasury_node_data(symbol, period=period, start_date=start_date.strftime("%Y-%m-%d"), end_date=end_date.strftime("%Y-%m-%d"))
            return fetch_treasury_node_data(symbol, period=period, start_date="", end_date="")

        if start_date is not None and end_date is not None:
            frame = yf.download(symbol, start=start_date.strftime("%Y-%m-%d"), end=(end_date + pd.Timedelta(days=1)).strftime("%Y-%m-%d"), interval="1d", progress=False)
            return normalize_price_dataframe(frame)
        frame = yf.download(symbol, period=period, interval="1d", progress=False)
        return normalize_price_dataframe(frame)

    scored = []
    for symbol in universe:
        if asset_type == "bond":
            data = fetch_window(symbol)
            s = score_bond_for_regime(data, regime)
        else:
            data = fetch_window(symbol)
            s = score_single_stock_for_regime(symbol, regime) if data is None or data.empty else score_single_stock_for_regime_window(data, regime)
        scored.append({
            "symbol": symbol.replace("=X", ""),
            "score": s.get("score", 50),
            "bias": s.get("bias", "Neutral"),
            "ret_1m": s.get("ret_1m", 0),
            "ret_3m": s.get("ret_3m", 0),
            "vol_ratio": s.get("vol_ratio", 1),
        })

    sorted_rows = sorted(scored, key=lambda x: (x["score"], x["ret_1m"], x["vol_ratio"]), reverse=True)
    return sorted_rows[:12]


def score_single_stock_for_regime_window(stock_data, regime):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return {"score": 50, "bias": "Neutral"}

    close = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
    volume = pd.Series(data["Volume"], index=data.index, dtype="float64").dropna() if "Volume" in data.columns else pd.Series(dtype="float64")
    if close.empty:
        return {"score": 50, "bias": "Neutral"}

    ret_21 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 22)]) - 1, 0) * 100 if len(close) > 22 else 0
    ret_63 = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 64)]) - 1, 0) * 100 if len(close) > 64 else ret_21
    vol_ratio = 1.0
    if not volume.empty and len(volume) > 40:
        vol_ratio = safe_float(volume.tail(10).mean() / max(volume.tail(40).mean(), 1), 1.0)

    base = 50 + (ret_21 * 0.6) + (ret_63 * 0.25) + ((vol_ratio - 1) * 10)
    if regime == "Expansion":
        base += max(0, ret_21) * 0.25
    elif regime == "Recession":
        base -= max(0, -ret_21) * 0.15
    elif regime == "Overheating":
        base += max(0, ret_21) * 0.1
    elif regime == "Stagflation":
        base -= abs(ret_21) * 0.05

    score = int(max(0, min(100, round(base))))
    bias = "Bullish" if score >= 65 else "Neutral" if score >= 45 else "Defensive"
    return {"score": score, "bias": bias, "ret_1m": round(ret_21, 2), "ret_3m": round(ret_63, 2), "vol_ratio": round(vol_ratio, 2)}


def parse_rss(url, source_name, limit=6):
    try:
        response = requests.get(url, timeout=20)
        response.raise_for_status()
        root = ET.fromstring(response.content)
        rows = []
        items = root.findall('.//item')
        for item in items[:limit]:
            title = (item.findtext('title') or '').strip()
            link = (item.findtext('link') or '').strip()
            pub_date = (item.findtext('pubDate') or '').strip()
            if title and link:
                rows.append({
                    "source": source_name,
                    "title": title,
                    "url": link,
                    "published": pub_date,
                })
        return rows
    except Exception:
        return []


def parse_news_timestamp(pub_date_text):
    text = (pub_date_text or "").strip()
    if not text:
        return None
    try:
        dt = parsedate_to_datetime(text)
        if dt is None:
            return None
        if dt.tzinfo is not None:
            dt = dt.astimezone(tz=None).replace(tzinfo=None)
        return pd.Timestamp(dt)
    except Exception:
        return None


def fetch_market_news(ticker, asset_type="stock", start_date=None, end_date=None, is_crisis_mode=False):
    if asset_type == "bond":
        query_suffix = "bond yields credit spreads fed rates"
    elif asset_type == "forex":
        query_suffix = "forex rates central bank"
    else:
        query_suffix = "stock market"
    if start_date is not None and end_date is not None:
        q_start = pd.to_datetime(start_date).strftime("%Y-%m-%d")
        q_end = pd.to_datetime(end_date).strftime("%Y-%m-%d")
        crisis_terms = "crisis OR recession OR default OR liquidity OR drawdown OR volatility"
        dated_query = quote_plus(f"{ticker} {query_suffix} {crisis_terms} after:{q_start} before:{q_end}")
        feeds = [
            (f"https://news.google.com/rss/search?q={dated_query}", "Google News Archive"),
            (f"https://feeds.finance.yahoo.com/rss/2.0/headline?s={quote_plus(ticker)}&region=US&lang=en-US", "Yahoo Finance"),
        ]
    else:
        ticker_query = quote_plus(f"{ticker} {query_suffix}")
        feeds = [
            (f"https://news.google.com/rss/search?q={ticker_query}", "Google News"),
            ("https://feeds.reuters.com/reuters/businessNews", "Reuters Business"),
            ("https://feeds.marketwatch.com/marketwatch/topstories/", "MarketWatch"),
            ("https://www.cnbc.com/id/100003114/device/rss/rss.html", "CNBC"),
            (f"https://feeds.finance.yahoo.com/rss/2.0/headline?s={quote_plus(ticker)}&region=US&lang=en-US", "Yahoo Finance"),
        ]

    merged = []
    seen_titles = set()
    for url, source in feeds:
        for row in parse_rss(url, source, limit=8):
            key = row["title"].lower()
            if key in seen_titles:
                continue
            seen_titles.add(key)
            merged.append(row)

    def _filter_to_window(rows):
        if start_date is None or end_date is None:
            return rows
        try:
            window_start = pd.Timestamp(start_date).tz_localize(None)
            window_end = pd.Timestamp(end_date).tz_localize(None)
        except Exception:
            return rows

        filtered = []
        for row in rows:
            ts = parse_news_timestamp(row.get("published"))
            if ts is None:
                continue
            if window_start <= ts <= (window_end + pd.Timedelta(days=1)):
                filtered.append(row)
        return filtered

    merged = _filter_to_window(merged)

    if is_crisis_mode and len(merged) < 8:
        fallback_query = quote_plus(f"{ticker} historical market crisis period")
        fallback_rows = _filter_to_window(parse_rss(f"https://news.google.com/rss/search?q={fallback_query}", "Google News", limit=18))
        for row in fallback_rows:
            key = row["title"].lower()
            if key in seen_titles:
                continue
            seen_titles.add(key)
            merged.append(row)

    if start_date is not None and end_date is not None:
        merged = sorted(merged, key=lambda row: parse_news_timestamp(row.get("published")) or pd.Timestamp.min, reverse=True)

    return merged[:18]


def build_rates_credit_snapshot(start_date, end_date):
    if start_date is None or end_date is None:
        return {"start": "N/A", "end": "N/A", "rows": []}

    def pick(series_id):
        try:
            series = fetch_fred_series(series_id, start_date - pd.DateOffset(months=1), end_date)
            if series.empty:
                return None, None
            start_val = _closest_value(series, start_date)
            end_val = _closest_value(series, end_date)
            if start_val is None or end_val is None:
                return None, None
            return float(start_val), float(end_val)
        except Exception:
            return None, None

    y2_s, y2_e = pick("DGS2")
    y10_s, y10_e = pick("DGS10")
    hy_s, hy_e = pick("BAMLH0A0HYM2")
    ig_s, ig_e = pick("BAMLC0A0CM")

    curve_s = None if y2_s is None or y10_s is None else y10_s - y2_s
    curve_e = None if y2_e is None or y10_e is None else y10_e - y2_e

    rows = [
        {"metric": "US 2Y Yield", "start": _to_serializable_float(y2_s, 2), "end": _to_serializable_float(y2_e, 2), "change": _to_serializable_float(None if y2_s is None or y2_e is None else y2_e - y2_s, 2), "unit": "%"},
        {"metric": "US 10Y Yield", "start": _to_serializable_float(y10_s, 2), "end": _to_serializable_float(y10_e, 2), "change": _to_serializable_float(None if y10_s is None or y10_e is None else y10_e - y10_s, 2), "unit": "%"},
        {"metric": "Yield Curve (10Y-2Y)", "start": _to_serializable_float(curve_s, 2), "end": _to_serializable_float(curve_e, 2), "change": _to_serializable_float(None if curve_s is None or curve_e is None else curve_e - curve_s, 2), "unit": "%"},
        {"metric": "HY Credit Spread", "start": _to_serializable_float(hy_s, 2), "end": _to_serializable_float(hy_e, 2), "change": _to_serializable_float(None if hy_s is None or hy_e is None else hy_e - hy_s, 2), "unit": "%"},
        {"metric": "IG Credit Spread", "start": _to_serializable_float(ig_s, 2), "end": _to_serializable_float(ig_e, 2), "change": _to_serializable_float(None if ig_s is None or ig_e is None else ig_e - ig_s, 2), "unit": "%"},
    ]
    return {"start": start_date.strftime("%Y-%m-%d"), "end": end_date.strftime("%Y-%m-%d"), "rows": rows}


def compute_forex_metrics(stock_data, start_date, end_date):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return {"rows": []}

    close = pd.Series(data["Close"], index=pd.to_datetime(data.index), dtype="float64").dropna()
    returns = close.pct_change().dropna()
    if close.empty:
        return {"rows": []}

    ret = (close.iloc[-1] / close.iloc[0] - 1) * 100 if len(close) > 1 else 0
    vol = returns.std() * np.sqrt(252) * 100 if len(returns) > 3 else 0
    tail = returns.quantile(0.05) * 100 if len(returns) > 20 else 0
    dd = _max_drawdown_pct(close)

    # DXY proxy relationship
    dxy = safe_download_series("DX-Y.NYB", close.index.min(), close.index.max())
    corr = returns.corr(dxy.pct_change().reindex(returns.index).dropna()) if not dxy.empty else np.nan
    beta = np.nan
    if not dxy.empty:
        dxy_ret = dxy.pct_change().reindex(returns.index).dropna()
        aligned = returns.reindex(dxy_ret.index).dropna()
        if len(aligned) > 20 and float(dxy_ret.var()) != 0:
            beta = np.cov(aligned, dxy_ret.reindex(aligned.index))[0][1] / dxy_ret.reindex(aligned.index).var()

    gap_freq = ((returns.abs() > (returns.std() * 2.0)) if len(returns) > 20 else pd.Series(dtype=bool)).mean() * 100 if len(returns) > 20 else 0
    stress_freq = ((returns < returns.quantile(0.1)) if len(returns) > 20 else pd.Series(dtype=bool)).mean() * 100 if len(returns) > 20 else 0

    rows = [
        {"metric": "Window Return", "value": _to_serializable_float(ret, 2), "unit": "%"},
        {"metric": "Annualized Volatility", "value": _to_serializable_float(vol, 2), "unit": "%"},
        {"metric": "Max Drawdown", "value": _to_serializable_float(dd, 2), "unit": "%"},
        {"metric": "5% Tail Return", "value": _to_serializable_float(tail, 2), "unit": "%"},
        {"metric": "DXY Correlation", "value": _to_serializable_float(corr, 3), "unit": ""},
        {"metric": "DXY Beta", "value": _to_serializable_float(beta, 3), "unit": ""},
        {"metric": "Shock-Day Frequency", "value": _to_serializable_float(stress_freq, 2), "unit": "%"},
        {"metric": "Gap/Jump Frequency", "value": _to_serializable_float(gap_freq, 2), "unit": "%"},
    ]

    return {
        "start": start_date.strftime("%Y-%m-%d") if start_date is not None else "N/A",
        "end": end_date.strftime("%Y-%m-%d") if end_date is not None else "N/A",
        "rows": rows,
    }


def safe_download_series(symbol, start_date, end_date):
    try:
        frame = yf.download(
            symbol,
            start=start_date.strftime("%Y-%m-%d"),
            end=(end_date + pd.Timedelta(days=1)).strftime("%Y-%m-%d"),
            interval="1d",
            progress=False,
        )
        frame = normalize_price_dataframe(frame)
        if frame is None or frame.empty or "Close" not in frame.columns:
            return pd.Series(dtype="float64")
        return pd.Series(frame["Close"], index=pd.to_datetime(frame.index), dtype="float64").dropna()
    except Exception:
        return pd.Series(dtype="float64")


@app.route('/api/latest_quote', methods=['GET'])
def latest_quote_api():
    ticker = request.args.get("ticker", "AAPL")
    asset_type = request.args.get("asset_type", "stock").strip().lower()
    normalized_ticker = normalize_ticker_for_asset(ticker, asset_type)
    try:
        if asset_type == "bond" and normalized_ticker in TREASURY_NODE_MAP:
            frame = fetch_treasury_node_data(normalized_ticker, period="1mo", start_date="", end_date="")
            if frame is None or frame.empty or "Close" not in frame.columns:
                return jsonify({"error": "No quote data"}), 400
            close_series = pd.Series(frame["Close"], index=frame.index, dtype="float64").dropna()
            if close_series.empty:
                return jsonify({"error": "No quote data"}), 400
            return jsonify({
                "ticker": normalized_ticker,
                "price": round(float(close_series.iloc[-1]), 6),
                "timestamp": str(close_series.index[-1]),
            })

        data = yf.download(normalized_ticker, period="5d", interval="1m")
        data = normalize_price_dataframe(data)
        if data is None or data.empty or "Close" not in data.columns:
            data = yf.download(normalized_ticker, period="1mo", interval="1d")
            data = normalize_price_dataframe(data)
        if data is None or data.empty or "Close" not in data.columns:
            return jsonify({"error": "No quote data"}), 400

        close_series = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
        if close_series.empty:
            return jsonify({"error": "No quote data"}), 400

        return jsonify({
            "ticker": normalized_ticker,
            "price": round(float(close_series.iloc[-1]), 6),
            "timestamp": str(close_series.index[-1]),
        })
    except Exception:
        return jsonify({"error": "Quote fetch failed"}), 500


def summarize_company_with_free_ai(company_name, business_text):
    prompt = (
        f"Write a concise investor-friendly overview in 3 bullets for {company_name}. "
        f"Business details: {business_text}. Mention business model, growth driver, and key risk."
    )
    endpoints = [
        "https://api-inference.huggingface.co/models/google/flan-t5-base",
        "https://api-inference.huggingface.co/models/facebook/bart-large-cnn",
    ]
    for endpoint in endpoints:
        try:
            response = requests.post(endpoint, json={"inputs": prompt}, timeout=25)
            if response.status_code != 200:
                continue
            data = response.json()
            if isinstance(data, list) and data and isinstance(data[0], dict):
                generated = data[0].get("generated_text") or data[0].get("summary_text")
                if generated:
                    return generated.strip()
            if isinstance(data, dict):
                generated = data.get("generated_text") or data.get("summary_text")
                if generated:
                    return str(generated).strip()
        except Exception:
            continue

    return (
        f"{company_name} snapshot: The company is operating in a growth-sensitive market, "
        f"with revenue potential linked to execution quality, demand durability, and margin discipline. "
        f"Traders should watch volume and post-listing volatility while investors track fundamentals over time."
    )


