def compute_orderflow_snapshot(stock_data):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty or "Close" not in data.columns:
        return {
            "flow_state": "Neutral",
            "pressure_score": 50,
            "buy_pressure": 50,
            "sell_pressure": 50,
            "volume_impulse": 1.0,
            "vwap_dislocation": 0.0,
            "note": "Insufficient data for orderflow-lite model.",
        }

    close = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
    open_p = pd.Series(data["Open"], index=data.index, dtype="float64").reindex(close.index).ffill()
    high = pd.Series(data["High"], index=data.index, dtype="float64").reindex(close.index).ffill()
    low = pd.Series(data["Low"], index=data.index, dtype="float64").reindex(close.index).ffill()
    volume = pd.Series(data["Volume"], index=data.index, dtype="float64").reindex(close.index).fillna(0)

    body = (close - open_p)
    range_series = (high - low).replace(0, pd.NA)
    candle_pressure = (body / range_series).fillna(0).tail(12).mean()
    typical = (high + low + close) / 3
    vwap = ((typical * volume).cumsum() / volume.replace(0, pd.NA).cumsum()).ffill()
    vwap_dislocation = safe_float(((close.iloc[-1] / max(vwap.iloc[-1], 0.0001)) - 1) * 100, 0)
    vol_short = safe_float(volume.tail(8).mean(), 0)
    vol_long = safe_float(volume.tail(40).mean(), 1)
    volume_impulse = vol_short / max(vol_long, 1)

    price_return = safe_float((close.iloc[-1] / close.iloc[max(0, len(close) - 6)] - 1) * 100, 0) if len(close) > 6 else 0
    buy_pressure = max(0, min(100, int(50 + candle_pressure * 35 + price_return * 0.9 + (volume_impulse - 1) * 16 + vwap_dislocation * 1.8)))
    sell_pressure = max(0, min(100, 100 - buy_pressure))
    pressure_score = max(0, min(100, int((buy_pressure * 0.65) + ((100 - sell_pressure) * 0.35))))

    if buy_pressure >= 62:
        flow_state = "Buyer Dominant"
    elif sell_pressure >= 62:
        flow_state = "Seller Dominant"
    else:
        flow_state = "Balanced / Choppy"

    return {
        "flow_state": flow_state,
        "pressure_score": pressure_score,
        "buy_pressure": buy_pressure,
        "sell_pressure": sell_pressure,
        "volume_impulse": round(volume_impulse, 2),
        "vwap_dislocation": round(vwap_dislocation, 2),
        "note": "Orderflow-lite model uses candle pressure, VWAP displacement, and relative volume. Upgrade to tick/L2 feeds for true orderflow.",
    }


def _max_drawdown_pct(equity_curve):
    if equity_curve is None or equity_curve.empty:
        return 0.0
    running_max = equity_curve.cummax().replace(0, np.nan)
    dd = (equity_curve / running_max) - 1
    if dd.empty:
        return 0.0
    return float(abs(dd.min()) * 100)


def build_strategy_catalog():
    catalog = []

    def add(strategy_id, name, family, engine, defaults, description):
        catalog.append({
            "id": strategy_id,
            "name": name,
            "family": family,
            "engine": engine,
            "defaults": defaults,
            "description": description,
        })

    for length, buy, sell in [(14, 30, 70), (14, 25, 75), (2, 5, 80), (21, 35, 65), (7, 30, 70), (9, 28, 72), (10, 32, 68), (6, 20, 80)]:
        add(f"rsi_reversal_{length}_{buy}_{sell}", f"RSI Reversal {length} ({buy}/{sell})", "Mean Reversion", "rsi_reversal", {"rsi_length": length, "rsi_buy": buy, "rsi_sell": sell}, "Buy oversold RSI and exit overbought RSI")

    for fast, slow in [(9, 21), (10, 30), (12, 26), (20, 50), (21, 55), (30, 100), (50, 200), (5, 20)]:
        add(f"ema_cross_{fast}_{slow}", f"EMA Cross {fast}/{slow}", "Trend", "ema_cross_custom", {"ema_fast": fast, "ema_slow": slow}, "Trend-following moving average crossover")

    for _id, name, th in [
        ("macd_classic", "MACD Signal Cross", 0),
        ("macd_zero", "MACD Zero-Line Shift", 0),
        ("ppo_signal", "PPO Signal Cross", 0),
        ("trix_momentum", "TRIX Momentum", 0),
        ("roc_positive", "ROC Positive Momentum", 0),
        ("aroon_trend", "Aroon Trend Shift", 0),
        ("adx_di_trend", "ADX + DI Trend", 22),
        ("supertrend_follow", "Supertrend Follow", 0),
        ("psar_flip", "Parabolic SAR Flip", 0),
        ("donchian_breakout", "Donchian Breakout", 0),
        ("keltner_breakout", "Keltner Breakout", 0),
        ("bbands_breakout", "Bollinger Breakout", 0),
        ("stoch_reversal", "Stochastic Reversal", 20),
        ("stochrsi_reversal", "Stoch RSI Reversal", 20),
        ("cci_reversal", "CCI Reversal", -100),
        ("williams_reversal", "Williams %R Reversal", -80),
        ("mfi_reversal", "MFI Reversal", 20),
        ("vwap_reclaim", "VWAP Reclaim", 0),
        ("obv_confirmation", "OBV Confirmation", 0),
        ("cmf_flow", "CMF Flow Filter", 0),
        ("forceindex_flip", "Force Index Flip", 0),
        ("ichimoku_kijun", "Ichimoku Kijun Cross", 0),
        ("ultimate_osc", "Ultimate Oscillator Thrust", 50),
        ("dpo_mean_revert", "DPO Mean Reversion", 0),
    ]:
        add(_id, name, "Momentum", _id, {"threshold": th}, "TradingView-style indicator strategy template")

    # Extra combinations to exceed 60 templates
    variant_count = 1
    for base, family, engine in [
        ("BB Mean Revert", "Mean Reversion", "bbands_revert"),
        ("Donchian Trend", "Breakout", "donchian_breakout"),
        ("VWAP Reclaim", "Intraday", "vwap_reclaim"),
        ("ADX Trend", "Trend", "adx_di_trend"),
        ("MACD Momentum", "Momentum", "macd_classic"),
        ("Stoch Reversal", "Mean Reversion", "stoch_reversal"),
        ("Supertrend", "Trend", "supertrend_follow"),
        ("CCI Reversion", "Mean Reversion", "cci_reversal"),
    ]:
        for threshold in [18, 20, 22, 25, 28]:
            add(
                f"{engine}_v{variant_count}",
                f"{base} Variant {variant_count}",
                family,
                engine,
                {"threshold": threshold},
                f"Variant tuned with threshold {threshold}",
            )
            variant_count += 1

    # Ensure custom builder is available as strategy option
    add("custom_builder", "Custom Indicator Builder", "Indicator Rules", "custom_builder", {}, "User-defined indicator and chart-tool rules")

    return catalog


def get_strategy_catalog_map():
    return {row["id"]: row for row in build_strategy_catalog()}


def run_backtest_simulation(stock_data, strategy_name, params):
    data = normalize_price_dataframe(stock_data)
    if data is None or data.empty:
        return {"error": "No data for backtest."}
    if any(col not in data.columns for col in ["Open", "High", "Low", "Close"]):
        return {"error": "Required OHLC fields missing for backtest."}

    data = data.dropna(subset=["Open", "High", "Low", "Close"]).copy()
    data.index = pd.to_datetime(data.index)
    data = data.sort_index()
    if len(data) < 20:
        return {"error": "Insufficient bars for backtest."}

    indicators = compute_indicator_series(data)
    close = pd.Series(data["Close"], index=data.index, dtype="float64").dropna()
    open_px = pd.Series(data["Open"], index=data.index, dtype="float64").reindex(close.index).ffill().dropna()
    high_px = pd.Series(data["High"], index=data.index, dtype="float64").reindex(close.index).ffill().dropna()
    low_px = pd.Series(data["Low"], index=data.index, dtype="float64").reindex(close.index).ffill().dropna()
    aligned_index = close.index.intersection(open_px.index)
    close = close.reindex(aligned_index)
    open_px = open_px.reindex(aligned_index)
    high_px = high_px.reindex(aligned_index).ffill()
    low_px = low_px.reindex(aligned_index).ffill()

    fee_bps = safe_float(params.get("fee_bps", 5), 5)
    slippage_bps = safe_float(params.get("slippage_bps", 3), 3)
    entry_cost = (fee_bps + slippage_bps) / 10000
    exit_cost = (fee_bps + slippage_bps) / 10000

    signal_buy = pd.Series(False, index=aligned_index)
    signal_sell = pd.Series(False, index=aligned_index)

    def indicator_series(name):
        key = (name or "").strip().lower()
        if key == "close":
            return close
        if key == "open":
            return open_px
        if key == "high":
            return pd.Series(data["High"], index=data.index, dtype="float64").reindex(aligned_index).ffill()
        if key == "low":
            return pd.Series(data["Low"], index=data.index, dtype="float64").reindex(aligned_index).ffill()
        if key == "volume":
            return pd.Series(data.get("Volume", pd.Series(0.0, index=data.index)), index=data.index, dtype="float64").reindex(aligned_index).fillna(0)
        if key in indicators:
            return pd.Series(indicators[key], index=data.index, dtype="float64").reindex(aligned_index)
        return pd.Series(np.nan, index=aligned_index, dtype="float64")

    def evaluate_rule(rule, idx):
        lhs_name = str(rule.get("lhs", "")).strip().lower()
        op = str(rule.get("op", "")).strip().lower()
        rhs_type = str(rule.get("rhs_type", "value")).strip().lower()
        lhs_series = indicator_series(lhs_name)
        if lhs_series.empty or idx >= len(lhs_series):
            return False
        lhs_val = lhs_series.iloc[idx]
        if pd.isna(lhs_val):
            return False

        if rhs_type == "indicator":
            rhs_name = str(rule.get("rhs_indicator", "")).strip().lower()
            rhs_series = indicator_series(rhs_name)
            rhs_val = rhs_series.iloc[idx] if idx < len(rhs_series) else np.nan
            prev_lhs = lhs_series.iloc[idx - 1] if idx > 0 else np.nan
            prev_rhs = rhs_series.iloc[idx - 1] if idx > 0 else np.nan
        else:
            rhs_val = safe_float(rule.get("rhs_value", 0), 0)
            prev_lhs = lhs_series.iloc[idx - 1] if idx > 0 else np.nan
            prev_rhs = rhs_val

        if pd.isna(rhs_val):
            return False

        if op == ">":
            return lhs_val > rhs_val
        if op == ">=":
            return lhs_val >= rhs_val
        if op == "<":
            return lhs_val < rhs_val
        if op == "<=":
            return lhs_val <= rhs_val
        if op == "crosses_above":
            return idx > 0 and (not pd.isna(prev_lhs)) and (not pd.isna(prev_rhs)) and prev_lhs <= prev_rhs and lhs_val > rhs_val
        if op == "crosses_below":
            return idx > 0 and (not pd.isna(prev_lhs)) and (not pd.isna(prev_rhs)) and prev_lhs >= prev_rhs and lhs_val < rhs_val
        return False

    def evaluate_rules(rules, idx):
        if not rules:
            return False
        return all(evaluate_rule(rule, idx) for rule in rules)

    chart_tools = params.get("chart_tools", []) if isinstance(params.get("chart_tools"), list) else []
    use_chart_tools = bool(params.get("use_chart_tools", False))

    def _to_day_ord(value):
        try:
            return int(pd.to_datetime(value).to_pydatetime().toordinal())
        except Exception:
            return None

    def build_chart_tool_rules(tools):
        trendlines = []
        horizontal_levels = []
        zones = []
        fib_levels = []

        for shape in tools:
            if not isinstance(shape, dict):
                continue
            shape_type = str(shape.get("type", "")).lower()
            x0 = shape.get("x0")
            x1 = shape.get("x1")
            y0 = shape.get("y0")
            y1 = shape.get("y1")

            x0o = _to_day_ord(x0)
            x1o = _to_day_ord(x1)
            if x0o is None or x1o is None:
                x0o = x1o = None

            if shape_type == "line" and y0 is not None and y1 is not None:
                try:
                    y0f = float(y0)
                    y1f = float(y1)
                except Exception:
                    continue

                if x0o is not None and x1o is not None and x0o != x1o:
                    slope = (y1f - y0f) / (x1o - x0o)
                    intercept = y0f - (slope * x0o)
                    trendlines.append({"slope": slope, "intercept": intercept})
                elif abs(y1f - y0f) < 1e-9:
                    horizontal_levels.append(y0f)

            if shape_type == "rect" and y0 is not None and y1 is not None:
                try:
                    low_band = min(float(y0), float(y1))
                    high_band = max(float(y0), float(y1))
                    zones.append((low_band, high_band))
                except Exception:
                    continue

            if shape_type == "line" and str(shape.get("line", {}).get("dash", "")).lower() == "dot" and y0 is not None:
                try:
                    fib_levels.append(float(y0))
                except Exception:
                    continue

        return {
            "trendlines": trendlines,
            "levels": horizontal_levels,
            "zones": zones,
            "fib_levels": fib_levels,
        }

    tool_rules = build_chart_tool_rules(chart_tools)

    def evaluate_chart_tool_signal(idx):
        if not use_chart_tools or idx <= 0:
            return {"entry_ok": True, "exit_ok": True}

        dt = aligned_index[idx]
        prev_close = float(close.iloc[idx - 1])
        curr_close = float(close.iloc[idx])
        day_ord = dt.to_pydatetime().toordinal()

        trend_cross_up = False
        trend_cross_down = False
        for tl in tool_rules["trendlines"]:
            y_line = (tl["slope"] * day_ord) + tl["intercept"]
            prev_y = (tl["slope"] * (day_ord - 1)) + tl["intercept"]
            if prev_close <= prev_y and curr_close > y_line:
                trend_cross_up = True
            if prev_close >= prev_y and curr_close < y_line:
                trend_cross_down = True

        level_break_up = any(prev_close <= lvl and curr_close > lvl for lvl in tool_rules["levels"])
        level_break_down = any(prev_close >= lvl and curr_close < lvl for lvl in tool_rules["levels"])

        zone_bounce_up = False
        zone_reject_down = False
        for low_band, high_band in tool_rules["zones"]:
            if prev_close <= high_band and prev_close >= low_band and curr_close > high_band:
                zone_bounce_up = True
            if prev_close <= high_band and prev_close >= low_band and curr_close < low_band:
                zone_reject_down = True

        fib_cross_up = any(prev_close <= lvl and curr_close > lvl for lvl in tool_rules["fib_levels"])
        fib_cross_down = any(prev_close >= lvl and curr_close < lvl for lvl in tool_rules["fib_levels"])

        entry_ok = trend_cross_up or level_break_up or zone_bounce_up or fib_cross_up
        exit_ok = trend_cross_down or level_break_down or zone_reject_down or fib_cross_down
        return {"entry_ok": entry_ok, "exit_ok": exit_ok}

    def template_signals(engine_name, threshold_value=0.0):
        def series(name):
            return indicator_series(name).reindex(aligned_index)

        if engine_name == "ema_cross_custom":
            fast = int(max(2, safe_float(params.get("ema_fast", 20), 20)))
            slow = int(max(fast + 1, safe_float(params.get("ema_slow", 50), 50)))
            ema_fast_s = close.ewm(span=fast, adjust=False).mean()
            ema_slow_s = close.ewm(span=slow, adjust=False).mean()
            return (ema_fast_s > ema_slow_s) & (ema_fast_s.shift(1) <= ema_slow_s.shift(1)), (ema_fast_s < ema_slow_s) & (ema_fast_s.shift(1) >= ema_slow_s.shift(1)), f"EMA Cross {fast}/{slow}"

        if engine_name in {"macd_classic", "macd_zero"}:
            macd = series("macd")
            sig = series("macd_signal")
            if engine_name == "macd_zero":
                return (macd > 0) & (macd.shift(1) <= 0), (macd < 0) & (macd.shift(1) >= 0), "MACD Zero Shift"
            return (macd > sig) & (macd.shift(1) <= sig.shift(1)), (macd < sig) & (macd.shift(1) >= sig.shift(1)), "MACD Signal Cross"

        if engine_name == "ppo_signal":
            ppo = series("ppo")
            ppo_sig = series("ppo_signal")
            return (ppo > ppo_sig) & (ppo.shift(1) <= ppo_sig.shift(1)), (ppo < ppo_sig) & (ppo.shift(1) >= ppo_sig.shift(1)), "PPO Signal Cross"

        if engine_name == "trix_momentum":
            trix = series("trix15")
            return (trix > threshold_value) & (trix.shift(1) <= threshold_value), (trix < threshold_value) & (trix.shift(1) >= threshold_value), "TRIX Momentum"

        if engine_name == "roc_positive":
            roc = series("roc12")
            return (roc > threshold_value) & (roc.shift(1) <= threshold_value), (roc < threshold_value) & (roc.shift(1) >= threshold_value), "ROC Momentum"

        if engine_name == "aroon_trend":
            up = series("aroon_up")
            dn = series("aroon_down")
            return (up > dn) & (up.shift(1) <= dn.shift(1)), (up < dn) & (up.shift(1) >= dn.shift(1)), "Aroon Trend Shift"

        if engine_name == "adx_di_trend":
            adx = series("adx")
            pdi = series("plus_di")
            mdi = series("minus_di")
            return (adx > max(15, threshold_value)) & (pdi > mdi), (adx > max(15, threshold_value)) & (pdi < mdi), "ADX DI Trend"

        if engine_name == "supertrend_follow":
            st = series("supertrend")
            return (close > st) & (close.shift(1) <= st.shift(1)), (close < st) & (close.shift(1) >= st.shift(1)), "Supertrend Follow"

        if engine_name == "psar_flip":
            psar = series("psar")
            return (close > psar) & (close.shift(1) <= psar.shift(1)), (close < psar) & (close.shift(1) >= psar.shift(1)), "Parabolic SAR Flip"

        if engine_name in {"donchian_breakout", "keltner_breakout", "bbands_breakout"}:
            if engine_name == "keltner_breakout":
                up = series("keltner_upper")
                dn = series("keltner_lower")
                name = "Keltner Breakout"
            elif engine_name == "bbands_breakout":
                up = series("bbands_upper")
                dn = series("bbands_lower")
                name = "Bollinger Breakout"
            else:
                up = series("donchian_upper")
                dn = series("donchian_lower")
                name = "Donchian Breakout"
            return (close > up) & (close.shift(1) <= up.shift(1)), (close < dn) & (close.shift(1) >= dn.shift(1)), name

        if engine_name in {"stoch_reversal", "stochrsi_reversal", "cci_reversal", "williams_reversal", "mfi_reversal", "ultimate_osc", "dpo_mean_revert"}:
            mapping = {
                "stoch_reversal": ("stoch_k", 20, 80, "Stochastic Reversal"),
                "stochrsi_reversal": ("stochrsi_k", 20, 80, "Stoch RSI Reversal"),
                "cci_reversal": ("cci20", -100, 100, "CCI Reversal"),
                "williams_reversal": ("williamsr14", -80, -20, "Williams %R Reversal"),
                "mfi_reversal": ("mfi14", 20, 80, "MFI Reversal"),
                "ultimate_osc": ("ultimateosc", 40, 60, "Ultimate Osc"),
                "dpo_mean_revert": ("dpo20", -0.1, 0.1, "DPO Mean Revert"),
            }
            key, lo_default, hi_default, label = mapping[engine_name]
            lo = threshold_value if threshold_value != 0 else lo_default
            hi = (100 - threshold_value) if key in {"stoch_k", "stochrsi_k", "mfi14", "ultimateosc"} and threshold_value != 0 else hi_default
            s = series(key)
            return (s <= lo) & (s.shift(1) > lo), (s >= hi) & (s.shift(1) < hi), label

        if engine_name in {"vwap_reclaim", "obv_confirmation", "cmf_flow", "forceindex_flip", "ichimoku_kijun", "bbands_revert"}:
            if engine_name == "vwap_reclaim":
                v = series("vwap")
                return (close > v) & (close.shift(1) <= v.shift(1)), (close < v) & (close.shift(1) >= v.shift(1)), "VWAP Reclaim"
            if engine_name == "obv_confirmation":
                obv = series("obv")
                obv_ma = obv.rolling(20).mean()
                return (obv > obv_ma) & (obv.shift(1) <= obv_ma.shift(1)), (obv < obv_ma) & (obv.shift(1) >= obv_ma.shift(1)), "OBV Confirmation"
            if engine_name == "cmf_flow":
                cmf = series("cmf20")
                return (cmf > threshold_value) & (cmf.shift(1) <= threshold_value), (cmf < threshold_value) & (cmf.shift(1) >= threshold_value), "CMF Flow"
            if engine_name == "forceindex_flip":
                f = series("forceindex13")
                return (f > threshold_value) & (f.shift(1) <= threshold_value), (f < threshold_value) & (f.shift(1) >= threshold_value), "Force Index Flip"
            if engine_name == "ichimoku_kijun":
                kijun = series("ichimoku_kijun")
                return (close > kijun) & (close.shift(1) <= kijun.shift(1)), (close < kijun) & (close.shift(1) >= kijun.shift(1)), "Ichimoku Kijun"
            if engine_name == "bbands_revert":
                low = series("bbands_lower")
                up = series("bbands_upper")
                return (close < low), (close > up), "BB Mean Revert"

        return pd.Series(False, index=aligned_index), pd.Series(False, index=aligned_index), "RSI Reversal"

    template_id = str(params.get("strategy_template_id") or "")
    if template_id:
        strategy_meta = get_strategy_catalog_map().get(template_id)
        if strategy_meta:
            strategy_name = strategy_meta.get("engine", strategy_name)
            for key, value in (strategy_meta.get("defaults") or {}).items():
                params.setdefault(key, value)

    if strategy_name == "custom_builder":
        entry_rules = params.get("entry_rules", []) if isinstance(params.get("entry_rules"), list) else []
        exit_rules = params.get("exit_rules", []) if isinstance(params.get("exit_rules"), list) else []
        if not entry_rules:
            return {"error": "Custom builder requires at least one entry rule."}
        strategy_label = "Custom Indicator Builder"
    elif strategy_name == "ema_cross":
        ema_fast = indicators.get("ema20", pd.Series(dtype="float64")).reindex(aligned_index)
        ema_slow = indicators.get("ema50", pd.Series(dtype="float64")).reindex(aligned_index)
        signal_buy = (ema_fast > ema_slow) & (ema_fast.shift(1) <= ema_slow.shift(1))
        signal_sell = (ema_fast < ema_slow) & (ema_fast.shift(1) >= ema_slow.shift(1))
        strategy_label = "EMA Cross 20/50"
    elif strategy_name not in {"rsi_reversal"}:
        signal_buy, signal_sell, strategy_label = template_signals(strategy_name, safe_float(params.get("threshold", 0), 0.0))
    else:
        rsi_len = max(2, min(60, int(safe_float(params.get("rsi_length", 14), 14))))
        rsi_buy = max(5, min(50, safe_float(params.get("rsi_buy", 30), 30)))
        rsi_sell = max(50, min(95, safe_float(params.get("rsi_sell", 70), 70)))
        rsi = indicators.get(f"rsi{rsi_len}")
        if rsi is None:
            # compute custom RSI length when not precomputed
            delta = close.diff()
            gain = delta.clip(lower=0)
            loss = -delta.clip(upper=0)
            avg_gain = gain.rolling(window=rsi_len).mean()
            avg_loss = loss.rolling(window=rsi_len).mean().replace(0, pd.NA)
            rs = avg_gain / avg_loss
            rsi = 100 - (100 / (1 + rs))
        rsi = pd.Series(rsi, index=aligned_index, dtype="float64").reindex(aligned_index)
        signal_buy = (rsi <= rsi_buy) & (rsi.shift(1) > rsi_buy)
        signal_sell = (rsi >= rsi_sell) & (rsi.shift(1) < rsi_sell)
        strategy_label = f"RSI Reversal ({rsi_len}, {int(rsi_buy)}/{int(rsi_sell)})"

    initial_capital = safe_float(params.get("initial_capital", 10000), 10000)
    allow_short = bool(params.get("allow_short", False))
    stop_loss_pct = max(0.0, safe_float(params.get("stop_loss_pct", 0), 0.0)) / 100.0
    take_profit_pct = max(0.0, safe_float(params.get("take_profit_pct", 0), 0.0)) / 100.0
    cash = initial_capital
    shares = 0.0
    position = 0
    entry_price = None
    entry_date = None

    equity_rows = []
    trades = []

    for i in range(len(aligned_index)):
        dt = aligned_index[i]
        signal_marker = None
        if i > 0:
            prev_dt = aligned_index[i - 1]
            current_close = float(close.iloc[i])
            current_high = float(high_px.iloc[i]) if i < len(high_px) else current_close
            current_low = float(low_px.iloc[i]) if i < len(low_px) else current_close

            if position == 1 and entry_price is not None:
                stop_level = entry_price * (1 - stop_loss_pct) if stop_loss_pct > 0 else None
                take_level = entry_price * (1 + take_profit_pct) if take_profit_pct > 0 else None
                hit_stop = stop_level is not None and current_low <= stop_level
                hit_take = take_level is not None and current_high >= take_level
                if hit_stop or hit_take:
                    # Conservative assumption: stop-loss triggers first if both touched in candle
                    if hit_stop:
                        trigger_price = stop_level
                        reason = "Stop Loss"
                    else:
                        trigger_price = take_level
                        reason = "Take Profit"
                    fill = float(trigger_price) * (1 - exit_cost)
                    cash = shares * fill
                    pnl_pct = ((fill / entry_price) - 1) * 100 if entry_price else 0
                    trades.append({
                        "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
                        "exit_date": dt.strftime("%Y-%m-%d"),
                        "entry_price": round(float(entry_price), 4) if entry_price else None,
                        "exit_price": round(float(fill), 4),
                        "pnl_pct": round(float(pnl_pct), 2),
                        "reason": reason,
                    })
                    shares = 0.0
                    position = 0
                    entry_price = None
                    entry_date = None
                    signal_marker = "SELL"

            chart_eval = evaluate_chart_tool_signal(i - 1)

            if position == 0 and ((strategy_name == "custom_builder" and evaluate_rules(entry_rules, i - 1)) or (strategy_name != "custom_builder" and bool(signal_buy.loc[prev_dt]))) and chart_eval["entry_ok"]:
                fill = float(open_px.iloc[i]) * (1 + entry_cost)
                if fill > 0:
                    shares = cash / fill
                    cash = 0.0
                    position = 1
                    entry_price = fill
                    entry_date = dt
                    signal_marker = "BUY"
            elif position == 1 and (((strategy_name == "custom_builder" and evaluate_rules(exit_rules, i - 1)) or (strategy_name != "custom_builder" and bool(signal_sell.loc[prev_dt]))) or (use_chart_tools and chart_eval["exit_ok"])):
                fill = float(open_px.iloc[i]) * (1 - exit_cost)
                cash = shares * fill
                pnl_pct = ((fill / entry_price) - 1) * 100 if entry_price else 0
                trades.append({
                    "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
                    "exit_date": dt.strftime("%Y-%m-%d"),
                    "entry_price": round(float(entry_price), 4) if entry_price else None,
                    "exit_price": round(float(fill), 4),
                    "pnl_pct": round(float(pnl_pct), 2),
                    "reason": "Signal Exit",
                })
                shares = 0.0
                position = 0
                entry_price = None
                entry_date = None
                signal_marker = "SELL"
            elif allow_short and position == 0 and ((strategy_name == "custom_builder" and evaluate_rules(exit_rules, i - 1)) or (strategy_name != "custom_builder" and bool(signal_sell.loc[prev_dt]))) and chart_eval["exit_ok"]:
                # short entry using sell signal
                fill = float(open_px.iloc[i]) * (1 - entry_cost)
                shares = cash / max(fill, 0.0001)
                cash = cash + (shares * fill)
                position = -1
                entry_price = fill
                entry_date = dt
                signal_marker = "SELL"
            elif position == -1 and (((strategy_name == "custom_builder" and evaluate_rules(entry_rules, i - 1)) or (strategy_name != "custom_builder" and bool(signal_buy.loc[prev_dt]))) or (use_chart_tools and chart_eval["entry_ok"])):
                fill = float(open_px.iloc[i]) * (1 + exit_cost)
                pnl_pct = ((entry_price / fill) - 1) * 100 if entry_price else 0
                cash = cash - (shares * fill)
                trades.append({
                    "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
                    "exit_date": dt.strftime("%Y-%m-%d"),
                    "entry_price": round(float(entry_price), 4) if entry_price else None,
                    "exit_price": round(float(fill), 4),
                    "pnl_pct": round(float(pnl_pct), 2),
                    "reason": "Signal Cover",
                })
                shares = 0.0
                position = 0
                entry_price = None
                entry_date = None
                signal_marker = "BUY"

            if position == -1 and entry_price is not None:
                stop_level = entry_price * (1 + stop_loss_pct) if stop_loss_pct > 0 else None
                take_level = entry_price * (1 - take_profit_pct) if take_profit_pct > 0 else None
                hit_stop = stop_level is not None and current_high >= stop_level
                hit_take = take_level is not None and current_low <= take_level
                if hit_stop or hit_take:
                    # Conservative assumption: stop-loss triggers first if both touched in candle
                    if hit_stop:
                        trigger_price = stop_level
                        reason = "Stop Loss"
                    else:
                        trigger_price = take_level
                        reason = "Take Profit"
                    fill = float(trigger_price) * (1 + exit_cost)
                    pnl_pct = ((entry_price / fill) - 1) * 100 if entry_price else 0
                    cash = cash - (shares * fill)
                    trades.append({
                        "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
                        "exit_date": dt.strftime("%Y-%m-%d"),
                        "entry_price": round(float(entry_price), 4) if entry_price else None,
                        "exit_price": round(float(fill), 4),
                        "pnl_pct": round(float(pnl_pct), 2),
                        "reason": reason,
                    })
                    shares = 0.0
                    position = 0
                    entry_price = None
                    entry_date = None
                    signal_marker = signal_marker or "BUY"

        if position == -1:
            equity = cash - (shares * float(close.iloc[i]))
        else:
            equity = cash + (shares * float(close.iloc[i]))
        equity_rows.append({
            "date": dt.strftime("%Y-%m-%d"),
            "open": round(float(open_px.iloc[i]), 4),
            "high": round(float(high_px.iloc[i]), 4),
            "low": round(float(low_px.iloc[i]), 4),
            "close": round(float(close.iloc[i]), 4),
            "equity": round(float(equity), 4),
            "signal": signal_marker,
        })

    if position == 1 and shares > 0:
        final_dt = aligned_index[-1]
        fill = float(close.iloc[-1]) * (1 - exit_cost)
        cash = shares * fill
        pnl_pct = ((fill / entry_price) - 1) * 100 if entry_price else 0
        trades.append({
            "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
            "exit_date": final_dt.strftime("%Y-%m-%d"),
            "entry_price": round(float(entry_price), 4) if entry_price else None,
            "exit_price": round(float(fill), 4),
            "pnl_pct": round(float(pnl_pct), 2),
            "reason": "Final Close",
        })
        if equity_rows:
            equity_rows[-1]["signal"] = equity_rows[-1]["signal"] or "SELL"

    if position == -1 and shares > 0:
        final_dt = aligned_index[-1]
        fill = float(close.iloc[-1]) * (1 + exit_cost)
        pnl_pct = ((entry_price / fill) - 1) * 100 if entry_price else 0
        cash = cash - (shares * fill)
        trades.append({
            "entry_date": entry_date.strftime("%Y-%m-%d") if entry_date is not None else None,
            "exit_date": final_dt.strftime("%Y-%m-%d"),
            "entry_price": round(float(entry_price), 4) if entry_price else None,
            "exit_price": round(float(fill), 4),
            "pnl_pct": round(float(pnl_pct), 2),
            "reason": "Final Cover",
        })
        if equity_rows:
            equity_rows[-1]["signal"] = equity_rows[-1]["signal"] or "BUY"

    equity_series = pd.Series([row["equity"] for row in equity_rows], index=pd.to_datetime([row["date"] for row in equity_rows]), dtype="float64")
    total_return = ((equity_series.iloc[-1] / initial_capital) - 1) * 100 if not equity_series.empty else 0
    day_count = max(1, int((equity_series.index[-1] - equity_series.index[0]).days)) if len(equity_series) > 1 else 1
    cagr = (((equity_series.iloc[-1] / initial_capital) ** (365 / day_count)) - 1) * 100 if equity_series.iloc[-1] > 0 else 0
    eq_ret = equity_series.pct_change().dropna()
    sharpe = float((eq_ret.mean() / eq_ret.std()) * np.sqrt(252)) if len(eq_ret) > 2 and float(eq_ret.std()) != 0 else 0.0
    wins = [t for t in trades if (t.get("pnl_pct") or 0) > 0]
    losses = [t for t in trades if (t.get("pnl_pct") or 0) <= 0]
    gross_gain = sum((t.get("pnl_pct") or 0) for t in wins)
    gross_loss = abs(sum((t.get("pnl_pct") or 0) for t in losses))
    profit_factor = gross_gain / gross_loss if gross_loss > 0 else float("inf")

    return {
        "strategy_name": strategy_label,
        "timeline": equity_rows,
        "trades": trades[:300],
        "metrics": {
            "total_return_pct": round(float(total_return), 2),
            "cagr_pct": round(float(cagr), 2),
            "max_drawdown_pct": round(float(_max_drawdown_pct(equity_series)), 2),
            "sharpe": round(float(sharpe), 2),
            "win_rate_pct": round((len(wins) / len(trades)) * 100, 2) if trades else 0,
            "profit_factor": "Inf" if profit_factor == float("inf") else round(float(profit_factor), 2),
            "trades": len(trades),
        },
    }


@app.route('/api/backtest', methods=['POST'])
def backtest_api():
    payload = request.get_json(silent=True) or {}
    ticker = payload.get("ticker", "AAPL")
    asset_type = str(payload.get("asset_type", "stock")).strip().lower()
    period = str(payload.get("period", "1y"))
    timeline_preset = str(payload.get("timeline_preset", "period"))
    start_date = str(payload.get("start_date", ""))
    end_date = str(payload.get("end_date", ""))
    strategy = str(payload.get("strategy", "rsi_reversal"))

    template_id = str(payload.get("strategy_template_id") or "")
    if template_id:
        meta = get_strategy_catalog_map().get(template_id)
        if meta:
            strategy = str(meta.get("engine", strategy))
            defaults = meta.get("defaults") or {}
            for key, value in defaults.items():
                payload.setdefault(key, value)
            payload.setdefault("strategy", strategy)

    normalized_ticker = normalize_ticker_for_asset(ticker, asset_type)
    stock_data, _ = fetch_stock_data(normalized_ticker, period, timeline_preset, start_date, end_date, asset_type)
    result = run_backtest_simulation(stock_data, strategy, payload)
    if "error" in result:
        return jsonify(result), 400
    result["ticker"] = normalized_ticker.upper()
    result["asset_type"] = asset_type
    return jsonify(result)


@app.route('/api/custom_chart', methods=['GET'])
def custom_chart_api():
    ticker = request.args.get("ticker", "AAPL")
    asset_type = request.args.get("asset_type", "stock").strip().lower()
    period = request.args.get("period", "1y")
    timeline_preset = request.args.get("timeline_preset", "period")
    is_crisis_mode = is_crisis_timeline_preset(timeline_preset)
    start_date = request.args.get("start_date", "")
    end_date = request.args.get("end_date", "")
    indicators = parse_csv_values(request.args.get("indicators", "sma20,sma50,ema20,rsi14,macd,bbands,atr14,stoch,obv,vwap,adx,ichimoku,roc12,williamsr14,cci20,mfi14,cmf20,donchian,keltner,supertrend,psar,ppo,trix15,stochrsi,mom10,ultimateosc,forceindex13,dpo20,hv20,adl,chaikinosc,aroon"))
    overlays = parse_csv_values(request.args.get("overlays", "vix,credit_spread_hy,credit_spread_ig,yield_2y,yield_10y,yield_curve_spread"))

    normalized_ticker = normalize_ticker_for_asset(ticker, asset_type)
    stock_data, timeline_label = fetch_stock_data(normalized_ticker, period, timeline_preset, start_date, end_date, asset_type)
    stock_data = normalize_price_dataframe(stock_data)
    if stock_data.empty:
        return jsonify({"error": "No stock data available for selected inputs."}), 400

    stock_data = stock_data.dropna(subset=["Open", "High", "Low", "Close"], how="any")
    stock_data.index = pd.to_datetime(stock_data.index)
    stock_data = stock_data.sort_index()
    indicator_map = compute_indicator_series(stock_data)
    macro_map = fetch_macro_overlay_series(overlays, stock_data.index)

    def aligned_values(series_name):
        series = indicator_map.get(series_name, pd.Series(dtype=float)).reindex(stock_data.index)
        return [None if pd.isna(v) else round(float(v), 4) for v in series.tolist()]

    indicator_payload = {}
    for name in indicators:
        if name == "bbands":
            indicator_payload["bbands_upper"] = aligned_values("bbands_upper")
            indicator_payload["bbands_mid"] = aligned_values("bbands_mid")
            indicator_payload["bbands_lower"] = aligned_values("bbands_lower")
        elif name == "macd":
            indicator_payload["macd"] = aligned_values("macd")
            indicator_payload["macd_signal"] = aligned_values("macd_signal")
            indicator_payload["macd_hist"] = aligned_values("macd_hist")
        elif name == "stoch":
            indicator_payload["stoch_k"] = aligned_values("stoch_k")
            indicator_payload["stoch_d"] = aligned_values("stoch_d")
        elif name == "ichimoku":
            indicator_payload["ichimoku_tenkan"] = aligned_values("ichimoku_tenkan")
            indicator_payload["ichimoku_kijun"] = aligned_values("ichimoku_kijun")
            indicator_payload["ichimoku_senkou_a"] = aligned_values("ichimoku_senkou_a")
            indicator_payload["ichimoku_senkou_b"] = aligned_values("ichimoku_senkou_b")
            indicator_payload["ichimoku_chikou"] = aligned_values("ichimoku_chikou")
        elif name == "donchian":
            indicator_payload["donchian_upper"] = aligned_values("donchian_upper")
            indicator_payload["donchian_mid"] = aligned_values("donchian_mid")
            indicator_payload["donchian_lower"] = aligned_values("donchian_lower")
        elif name == "keltner":
            indicator_payload["keltner_upper"] = aligned_values("keltner_upper")
            indicator_payload["keltner_mid"] = aligned_values("keltner_mid")
            indicator_payload["keltner_lower"] = aligned_values("keltner_lower")
        elif name == "supertrend":
            indicator_payload["supertrend"] = aligned_values("supertrend")
            indicator_payload["supertrend_dir"] = aligned_values("supertrend_dir")
        elif name == "ppo":
            indicator_payload["ppo"] = aligned_values("ppo")
            indicator_payload["ppo_signal"] = aligned_values("ppo_signal")
            indicator_payload["ppo_hist"] = aligned_values("ppo_hist")
        elif name == "stochrsi":
            indicator_payload["stochrsi_k"] = aligned_values("stochrsi_k")
            indicator_payload["stochrsi_d"] = aligned_values("stochrsi_d")
        elif name == "aroon":
            indicator_payload["aroon_up"] = aligned_values("aroon_up")
            indicator_payload["aroon_down"] = aligned_values("aroon_down")
        elif name in indicator_map:
            indicator_payload[name] = aligned_values(name)

    macro_payload = {
        name: [None if pd.isna(v) else round(float(v), 4) for v in series.reindex(stock_data.index).tolist()]
        for name, series in macro_map.items()
    }

    response_payload = {
        "ticker": normalized_ticker.upper(),
        "asset_type": asset_type,
        "timeline_label": timeline_label,
        "is_crisis_mode": is_crisis_mode,
        "dates": [idx.strftime("%Y-%m-%d") for idx in stock_data.index],
        "open": [round(float(v), 4) for v in stock_data["Open"].tolist()],
        "high": [round(float(v), 4) for v in stock_data["High"].tolist()],
        "low": [round(float(v), 4) for v in stock_data["Low"].tolist()],
        "close": [round(float(v), 4) for v in stock_data["Close"].tolist()],
        "volume": [0 if pd.isna(v) else int(v) for v in stock_data["Volume"].fillna(0).tolist()],
        "indicators": indicator_payload,
        "macro": macro_payload,
    }
    return jsonify(response_payload)


